                        onClick={() => setShowMenu(!showMenu)}
                        className={`p-2 rounded-xl transition-colors ${showMenu ? 'bg-red-500/20 text-red-400' : 'text-stone-400 hover:text-white hover:bg-white/5'}`}
                    >
                        <Menu size={20} />
                    </button>
                </div>

                {/* Menu Dropdown */}
