                                            label="Hoplite"
                                            cost={{ food: 200, gold: 150 }}
                                            stats={stats}
                                            onClick={() => onSpawnUnit(UnitType.HOPLITE)}
                                            icon={<Shield size={16} />}
                                          />
                                        )}
                                        {AGE_CONFIGS[stats.currentAge].unlocksUnits.includes(UnitType.CHARIOT) && (
