        const spacing = 15;
        const groupOffsets = FormationSystem.getFormationOffsets(this.currentFormation, units.length, spacing);

        let rotationAngle = 0;
        if (this.currentFormation === FormationType.LINE || this.currentFormation === FormationType.WEDGE) {
            let sumX = 0, sumY = 0;
