const CELL = 32; // Must match MapGenerationSystem's tree collision grid        

// â”€â”€â”€ Priority Queue (Min-Heap) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”
€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â
”€â”€â”€â”€
class MinHeap<T> {
    private items: { key: number; value: T }[] = [];

    get size(): number { return this.items.length; }

    push(key: number, value: T): void {
        this.items.push({ key, value });
        this.siftUp(this.items.length - 1);
    }

    pop(): T | null {
        if (this.items.length === 0) return null;
        const top = this.items[0].value;
        const last = this.items.pop()!;
        if (this.items.length > 0) {
            this.items[0] = last;
            this.siftDown(0);
        }
        return top;
    }

    private siftUp(idx: number): void {
        while (idx > 0) {
            const parentIdx = (idx - 1) >> 1;
            if (this.items[idx].key >= this.items[parentIdx].key) break;        
            [this.items[idx], this.items[parentIdx]] = [this.items[parentIdx], t
his.items[idx]];
            idx = parentIdx;
        }
    }

    private siftDown(idx: number): void {
        const size = this.items.length;
        while (true) {
            let smallest = idx;
            const left = (idx << 1) + 1;
            const right = left + 1;
            if (left < size && this.items[left].key < this.items[smallest].key) 
smallest = left;
            if (right < size && this.items[right].key < this.items[smallest].key
) smallest = right;
            if (smallest === idx) break;
            [this.items[idx], this.items[smallest]] = [this.items[smallest], thi
s.items[idx]];
            idx = smallest;
        }
    }
}

