                nearest.gy * CELL + CELL / 2
            );
            return this.findPath(newStart, end);
        }

        // Run JPS
        this.frameStats.jpsCalls++;
        this.totals.jpsCalls++;
        const path = this.jps(sx, sy, ex, ey);

        if (!path || path.length === 0) {
            const _ms = performance.now() - _pfT0; this.frameStats.pathMs += _ms; this.totals.pathMs += _ms;
            return [new Phaser.Math.Vector2(start.x, start.y)];
        }

        this.pathsComputed++;

        // Convert grid coords to world coords (center of cell)
        const _ms = performance.now() - _pfT0; this.frameStats.pathMs += _ms; this.totals.pathMs += _ms;
        return path.map(p => new Phaser.Math.Vector2(
            p.gx * CELL + CELL / 2,
            p.gy * CELL + CELL / 2
        ));
    }

    /**
     * Jump Point Search implementation.
     */
    private jps(sx: number, sy: number, ex: number, ey: number): { gx: number; gy: number }[] | null {
        // Bump version to clear stale state
        this.currentVersion = (this.currentVersion + 1) & 0xFFFF;
        const v = this.currentVersion;

        const open = new MinHeap<number>();
        const startIdx = this.idx(sx, sy);
        const endIdx = this.idx(ex, ey);

        this.nodeG[startIdx] = 0;
        this.nodeParent[startIdx] = -1;
        this.nodeVersion[startIdx] = v;
        this.nodeOpen[startIdx] = 1;

        open.push(octileDistance(sx, sy, ex, ey), startIdx);

        while (open.size > 0) {
            const currentIdx = open.pop()!;

            if (currentIdx === endIdx) {
                return this.reconstructPath(currentIdx, v);
            }

            this.nodeOpen[currentIdx] = 2; // Closed

            const { gx, gy } = this.coord(currentIdx);

            // Identify successors using JPS pruning
            const parentIdx = this.nodeParent[currentIdx];
            let px = -1, py = -1;
            if (parentIdx >= 0) {
                const p = this.coord(parentIdx);
                px = p.gx; py = p.gy;
            }

            const neighbors = this.getSuccessors(gx, gy, px, py);

            for (const [nx, ny] of neighbors) {
                // Jump to find the next significant node
                const jumpPoint = this.jump(nx, ny, gx, gy, ex, ey);
                if (!jumpPoint) continue;

                const nIdx = this.idx(jumpPoint.gx, jumpPoint.gy);
                if (this.nodeVersion[nIdx] === v && this.nodeOpen[nIdx] === 2) continue;

                const dist = octileDistance(gx, gy, jumpPoint.gx, jumpPoint.gy);
                const tentG = this.nodeG[currentIdx] + dist;

                if (this.nodeVersion[nIdx] !== v || this.nodeOpen[nIdx] === 0) {
                    this.nodeVersion[nIdx] = v;
                    this.nodeG[nIdx] = tentG;
                    this.nodeParent[nIdx] = currentIdx;
                    this.nodeOpen[nIdx] = 1;
                    const f = tentG + octileDistance(jumpPoint.gx, jumpPoint.gy, ex, ey);
                    open.push(f, nIdx);
                } else if (tentG < this.nodeG[nIdx]) {
                    this.nodeG[nIdx] = tentG;
                    this.nodeParent[nIdx] = currentIdx;
                    const f = tentG + octileDistance(jumpPoint.gx, jumpPoint.gy, ex, ey);
                    open.push(f, nIdx);
                }
            }
        }

        return null; // No path found
    }

    /**
     * Get pruned neighbor set based on direction from parent.
     * Uses JPS natural + forced neighbor pruning rules.
     */
    private getSuccessors(gx: number, gy: number, px: number, py: number): [number, number][] {
        const neighbors: [number, number][] = [];

        if (px < 0 && py < 0) {
            // No parent: explore all 8 directions
            for (let d = 0; d < 8; d++) {
                const nx = gx + Pathfinder.DX[d];
                const ny = gy + Pathfinder.DY[d];
                if (this.isValid(nx, ny) && !this.isCellBlocked(this.idx(nx, ny))) {
                    neighbors.push([nx, ny]);
                }
            }
            return neighbors;
        }

        // Direction from parent to current
        const dx = Math.sign(gx - px);
        const dy = Math.sign(gy - py);
        // Normalize to diagonal axis
        const dxx = Math.abs(dx);
        const dyy = Math.abs(dy);

        if (dxx === 1 && dyy === 1) {
            // Diagonal movement
            // Natural: the diagonal neighbor
            if (this.isWalkable(gx + dx, gy + dy)) neighbors.push([gx + dx, gy + dy]);
            // Natural: the cardinal neighbors in the direction
            if (this.isWalkable(gx + dx, gy)) neighbors.push([gx + dx, gy]);
            if (this.isWalkable(gx, gy + dy)) neighbors.push([gx, gy + dy]);
            // Forced neighbors for diagonal
            if (!this.isWalkable(gx - dx, gy) && this.isWalkable(gx + dx, gy)) {
                // Force the diagonal if one side is blocked
            }
            if (!this.isWalkable(gx, gy - dy) && this.isWalkable(gx, gy + dy)) {
                // Force the diagonal if one side is blocked
            }
        } else if (dxx === 1) {
            // Horizontal movement (dy = 0)
            if (this.isWalkable(gx + dx, gy)) neighbors.push([gx + dx, gy]);
            // Forced neighbors
            if (!this.isWalkable(gx, gy - 1) && this.isWalkable(gx + dx, gy - 1))
                neighbors.push([gx + dx, gy - 1]);
            if (!this.isWalkable(gx, gy + 1) && this.isWalkable(gx + dx, gy + 1))
                neighbors.push([gx + dx, gy + 1]);
        } else {
            // Vertical movement (dx = 0, dy = 1 or -1)
            if (this.isWalkable(gx, gy + dy)) neighbors.push([gx, gy + dy]);
            // Forced neighbors
            if (!this.isWalkable(gx - 1, gy) && this.isWalkable(gx - 1, gy + dy))
                neighbors.push([gx - 1, gy + dy]);
            if (!this.isWalkable(gx + 1, gy) && this.isWalkable(gx + 1, gy + dy))
                neighbors.push([gx + 1, gy + dy]);
        }

        return neighbors;
    }

    /**
     * Jump function: traverse until hitting a "jump point".
     */
    private jump(gx: number, gy: number, px: number, py: number, ex: number, ey: number): { gx: number; gy: number } | null {
        if (!this.isWalkable(gx, gy)) return null;
        if (gx === ex && gy === ey) return { gx, gy };

        const dx = gx - px;
        const dy = gy - py;
        const dxx = Math.abs(dx);
        const dyy = Math.abs(dy);

        // Check for forced neighbors
        if (dxx === 1 && dyy === 1) {
            // Diagonal: check if there's a forced neighbor
            if ((!this.isWalkable(gx - dx, gy) && this.isWalkable(gx - dx, gy + dy)) ||
                (!this.isWalkable(gx, gy - dy) && this.isWalkable(gx + dx, gy - dy))) {
                return { gx, gy };
            }
            // Recursively jump in cardinal directions first
            if (this.jump(gx + dx, gy, gx, gy, ex, ey) || this.jump(gx, gy + dy, gx, gy, ex, ey)) {
                return { gx, gy };
            }
            // Continue diagonal jump
            if (this.isWalkable(gx + dx, gy + dy)) {
                return this.jump(gx + dx, gy + dy, gx, gy, ex, ey);
            }
        } else if (dxx === 1) {
            // Horizontal
            if ((!this.isWalkable(gx, gy - 1) && this.isWalkable(gx + dx, gy - 1)) ||
                (!this.isWalkable(gx, gy + 1) && this.isWalkable(gx + dx, gy + 1))) {
                return { gx, gy };
            }
            if (this.isWalkable(gx + dx, gy)) {
                return this.jump(gx + dx, gy, gx, gy, ex, ey);
            }
        } else {
            // Vertical
            if ((!this.isWalkable(gx - 1, gy) && this.isWalkable(gx - 1, gy + dy)) ||
                (!this.isWalkable(gx + 1, gy) && this.isWalkable(gx + 1, gy + dy))) {
                return { gx, gy };
            }
            if (this.isWalkable(gx, gy + dy)) {
                return this.jump(gx, gy + dy, gx, gy, ex, ey);
            }
        }

        return null;
    }

    private isCellBlocked(i: number): boolean {
        return this.blocked[i] === 1 || this.waterBlocked[i] === 1;
    }

    private isWalkable(gx: number, gy: number): boolean {
        if (!this.isValid(gx, gy)) return false;
        return !this.isCellBlocked(this.idx(gx, gy));
    }

    private reconstructPath(endIdx: number, version: number): { gx: number; gy: number }[] {
        const path: { gx: number; gy: number }[] = [];
        let current = endIdx;
        while (current >= 0 && this.nodeVersion[current] === version) {
            const c = this.coord(current);
            path.unshift(c);
            const parent = this.nodeParent[current];
            if (parent < 0) break;
            current = parent;
        }
        return path;
    }

    // ─── Flow Field Generation ────────────────────────────────────────────
    /**
     * Generate a flow field for mass unit movement.
     * All units moving to the same destination share one flow field.
     * Returns a lookup function that gives direction vectors.
     */
    public generateFlowField(targetX: number, targetY: number): { dirX: Float64Array; dirY: Float64Array; cols: number; rows: number; targetX: number; targetY: number } {
        const tgx = this.gridX(targetX);
        const tgy = this.gridY(targetY);
        const key = `${tgx},${tgy}`;

        const cached = this.flowFieldCache.get(key);
        if (cached) return cached;

        const genT0 = performance.now();
        const total = this.gridCols * this.gridRows;
        const integration = new Float64Array(total);
        const dirX = new Float64Array(total);
        const dirY = new Float64Array(total);
        integration.fill(Number.MAX_VALUE);

        // BFS from target outward
        const queue: number[] = [];
        const targetIdx = this.idx(tgx, tgy);

        if (!this.isCellBlocked(targetIdx)) {
            integration[targetIdx] = 0;
            dirX[targetIdx] = 0;
            dirY[targetIdx] = 0;
            queue.push(targetIdx);
        } else {
            // Target blocked: seed from neighbors
            for (let d = 0; d < 8; d++) {
                const nx = tgx + Pathfinder.DX[d];
                const ny = tgy + Pathfinder.DY[d];
                if (this.isWalkable(nx, ny)) {
                    const nIdx = this.idx(nx, ny);
                    integration[nIdx] = 1;
                    dirX[nIdx] = -Pathfinder.DX[d];
                    dirY[nIdx] = -Pathfinder.DY[d];
                    queue.push(nIdx);
                }
            }
        }

        // BFS propagation (Dijkstra-like)
        let qIdx = 0;
        while (qIdx < queue.length) {
            const currentIdx = queue[qIdx++];
            const cur = this.coord(currentIdx);
            const baseCost = integration[currentIdx];

            for (let d = 0; d < 8; d++) {
                const nx = cur.gx + Pathfinder.DX[d];
                const ny = cur.gy + Pathfinder.DY[d];
                if (!this.isWalkable(nx, ny)) continue;

                const nIdx = this.idx(nx, ny);
                // Diagonal movement costs more
                const moveCost = (Pathfinder.DX[d] !== 0 && Pathfinder.DY[d] !== 0) ? Math.SQRT2 : 1;
                const newCost = baseCost + moveCost * this.costs[nIdx];

                if (newCost < integration[nIdx]) {
                    integration[nIdx] = newCost;
                    dirX[nIdx] = -Pathfinder.DX[d];
                    dirY[nIdx] = -Pathfinder.DY[d];
                    queue.push(nIdx);
                }
            }
        }

        this.flowFieldsGenerated++;
        const result = { dirX, dirY, cols: this.gridCols, rows: this.gridRows, targetX, targetY, version: this.gridVersion };

        // Cache (invalidate when blocks change)
        if (this.flowFieldCache.size > 10) {
            // LRU: delete oldest
            const firstKey = this.flowFieldCache.keys().next().value;
            if (firstKey !== undefined) this.flowFieldCache.delete(firstKey);
        }
        this.flowFieldCache.set(key, result);

        const genMs = performance.now() - genT0;
        this.frameStats.flowFieldMs += genMs;
        this.frameStats.flowFieldRebuilds++;
        this.totals.flowFieldMs += genMs;
        this.totals.flowFieldRebuilds++;
        return result;
    }

    /**
     * Get flow direction for a specific world position.
     */
    public getFlowDirection(flowField: { dirX: Float64Array; dirY: Float64Array; cols: number; rows: number; version?: number }, x: number, y: number): { x: number; y: number } | null {
        // Stale flow field (grid changed since it was built) — unit must re-acquire
        if (flowField.version !== undefined && flowField.version !== this.gridVersion) return null;
        const gx = this.gridX(x);
        const gy = this.gridY(y);
        if (!this.isValid(gx, gy)) return null;

        const idx = this.idx(gx, gy);
        if (this.isCellBlocked(idx)) return null;

        const dx = flowField.dirX[idx];
        const dy = flowField.dirY[idx];

        // No direction = arrived or unreachable
        if (dx === 0 && dy === 0) {
            return { x: 0, y: 0 };
        }

        // Normalize
        const len = Math.sqrt(dx * dx + dy * dy);
        if (len < 0.001) return null;
        return { x: dx / len, y: dy / len };
    }

    // ─── Path Request Queue (for async/batched pathfinding) ───────────────
    /**
     * Queue a pathfinding request. Callback fires when path is computed.
     * Use this for non-urgent paths to spread computation across frames.
     */
    public requestPath(
        start: Phaser.Math.Vector2,
        end: Phaser.Math.Vector2,
        callback: (path: Phaser.Math.Vector2[] | null) => void
    ): number {
        const id = this.nextRequestId++;
        this.requestQueue.push({ id, start, end, callback });
        return id;
    }

    /**
     * Cancel a queued path request.
     */
    public cancelRequest(id: number): void {
        this.requestQueue = this.requestQueue.filter(r => r.id !== id);
    }

    /**
     * Process queued path requests (call once per frame).
     * Computes up to maxPathsPerFrame paths.
     */
    public processQueue(): void {
        let processed = 0;
        while (this.requestQueue.length > 0 && processed < this.maxPathsPerFrame) {
            const req = this.requestQueue.shift()!;
            const path = this.findPath(req.start, req.end);
            req.callback(path);
            processed++;
        }
        this.frameStats.queueProcessed += processed;
        this.totals.queueProcessed += processed;
    }

    /**
     * Budgeted queue processing for large unit counts.
     * Only processes up to `budget` items per call, preserving rest for next frame.
     */
    public processQueueBudgeted(budget: number): void {
        let processed = 0;
        while (this.requestQueue.length > 0 && processed < budget) {
            const req = this.requestQueue.shift()!;
            const path = this.findPath(req.start, req.end);
            req.callback(path);
            processed++;
        }
        this.frameStats.queueProcessed += processed;
        this.totals.queueProcessed += processed;
    }

    // ─── Utility ───────────────────────────────────────────────────────────
    private findNearestUnblockedGrid(gx: number, gy: number): { gx: number; gy: number } | null {
        // Search expanding rings
        for (let radius = 1; radius <= 15; radius++) {
            for (let dx = -radius; dx <= radius; dx++) {
                for (let dy = -radius; dy <= radius; dy++) {
                    if (Math.abs(dx) !== radius && Math.abs(dy) !== radius) continue;
                    const nx = gx + dx;
                    const ny = gy + dy;
                    if (this.isWalkable(nx, ny)) {
                        return { gx: nx, gy: ny };
                    }
                }
            }
        }
        return null;
    }

    /** Reset per-frame counters. Call at start of each game frame. */
    public beginFrame(): void {
        this.frameStats.jpsCalls = 0;
        this.frameStats.pathMs = 0;
        this.frameStats.flowFieldRebuilds = 0;
        this.frameStats.flowFieldMs = 0;
        this.frameStats.queueProcessed = 0;
        this.frameStats.queueDropped = 0;
        this.totals.frames++;
    }

    /** Get diagnostics snapshot including per-frame averages. */
    public getCacheStats(): { flowFieldCaches: number; queueSize: number; pathsComputed: number; flowFieldsGenerated: number; gridVersion: number; queueDepth: number; droppedRequests: number } {
        return {
            flowFieldCaches: this.flowFieldCache.size,
            queueSize: this.requestQueue.length,
            pathsComputed: this.pathsComputed,
            flowFieldsGenerated: this.flowFieldsGenerated,
            gridVersion: this.gridVersion,
            queueDepth: this.requestQueue.length,
            droppedRequests: this.droppedRequests,
        };
    }

    /** Averages-per-frame from cumulative totals. Used by PERF report. */
    public getPerfReport(): { avgPathMs: number; avgFlowMs: number; avgJpsCalls: number; avgQueueProcessed: number; avgQueueDropped: number; frames: number } {
        const n = Math.max(1, this.totals.frames);
        return {
            avgPathMs: this.totals.pathMs / n,
            avgFlowMs: this.totals.flowFieldMs / n,
            avgJpsCalls: this.totals.jpsCalls / n,
            avgQueueProcessed: this.totals.queueProcessed / n,
            avgQueueDropped: this.totals.queueDropped / n,
            frames: this.totals.frames,
        };
    }
}

import Phaser from 'phaser';
import { MainScene } from '../MainScene';
import { UnitType, GameUnit } from '../../types';

/**
 * LiquidCombatSystem — produces the visual illusion of liquid mass melee.
 *
 * Three cheap, scalable forces (no Navier-Stokes, no fluid engine):
 *
 * 1. Pressure        — high-density SpatialHash cells push units outward.
 *                      Front lines compress naturally; units squeeze around congestion.
 * 2. Contact line    — opposing-formation pairs detected once per frame (m = formations,
 *                      NOT n = units). At contact boundaries, push backward + lateral tangent.
 *                      Contact lines ripple and bend instead of stopping abruptly.
 * 3. Velocity align  — lerp each unit's velocity toward neighbor average. Kills jitter,
 *                      makes the mass flow coherently instead of chaos.
 *
 * Integration: the per-unit force application lives inside UnitSystem's existing
 * rotating bucket (maxUnitsPerFrame) — see UnitSystem.applyLiquidSteering().
 * This system only does the once-per-frame precomputation (pressure grid + contact lines).
 * Velocity alignment is done per-unit in the bucket pass to avoid a second O(n) neighbor sweep.
 *
 * Performance:
 * - Pressure: O(cells with units) ≈ O(n) but with tiny constant (Map lookup + counter).
 * - Contact:  O(formations²) where formations << units (we group by owner + 150px cell).
 * - Align:    O(n × neighbors) but piggybacks on the existing separation tick interval
 *             and reuses the same SpatialHash.query() results — no double sweep.
 *
 * The visual payoff: two armies collide → dense front compresses → pressure propagates
 * → contact line ripples sideways → units flow around congestion → formations deform
 * but maintain cohesion via alignment. Reads as "wall of bodies" from RTS camera.
 */

// ─── Tuning constants ────────────────────────────────────────────────────
// All forces are velocity-space nudges (units/sec²), NOT positional displacement.

/** Pressure: units per cell at which pressure is "maxed" (outward push saturates). */
const PRESSURE_DENSITY_MAX = 8;
/** Pressure: max outward push strength (px/s applied to velocity). */
const PRESSURE_FORCE_MAX = 60;
/** Pressure: how strongly density above baseline generates force. Quadratic = realistic compression. */
const PRESSURE_CURVE = 2.0;

/** Contact line: max distance (px) at which opposing forces still apply. */
const CONTACT_RANGE = 100;
/** Contact line: backward push strength (push away from enemy). */
const CONTACT_BACKWARD_FORCE = 80;
/** Contact line: lateral tangent push strength (flow along the front). */
const CONTACT_LATERAL_FORCE = 50;
/** Contact line: how far (px) to sample the enemy centroid for normal calculation. */
const CONTACT_SAMPLE_RADIUS = 80;

/** Velocity alignment: max neighbor query radius (px). */
const ALIGN_RADIUS = 30;
/** Velocity alignment: max interpolation factor toward neighbor average (per application). */
const ALIGN_STRENGTH = 0.15;
/** Velocity alignment: min neighbor count before alignment kicks in (avoid lone-unit drift). */
const ALIGN_MIN_NEIGHBORS = 2;

/** SpatialHash cell size (must match MainScene's unitSpatialHash = 150). */
const CELL_SIZE = 150;

// ─── Types ───────────────────────────────────────────────────────────────

interface CellPressure {
    /** Outward pressure direction + magnitude (normalized × force). */
    dirX: number;
    dirY: number;
    /** Raw force magnitude for this cell. */
    force: number;
    /** Unit count. */
    density: number;
}

interface ContactLine {
    /** Contact boundary center. */
    x: number;
    y: number;
    /** Normal pointing from friendly → enemy. */
    nx: number;
    ny: number;
    /** Tangent (perpendicular to normal) for lateral flow. */
    tx: number;
    ty: number;
    /** Strength 0–1 based on proximity of the two formations. */
    strength: number;
    /** Which owner this contact affects (the friendly side). */
    owner: number;
}

// ─── System ──────────────────────────────────────────────────────────────

export class LiquidCombatSystem {
    private scene: MainScene;

    /** Per-frame pressure grid, keyed by "cx,cy" SpatialHash cell key. */
    private pressureGrid: Map<string, CellPressure> = new Map();

    /** Per-frame contact lines, one per opposing formation pair. */
    private contactLines: ContactLine[] = [];

    /** Diagnostic: whether liquid combat is active (disabled in peaceful/stress-peaceful). */
    public enabled: boolean = true;

    constructor(scene: MainScene) {
        this.scene = scene;
    }

    /**
     * Once-per-frame precomputation. Called BEFORE UnitSystem's bucket pass so
     * the pressure grid and contact lines are ready for per-unit force application.
     *
     * Cost: O(units) for pressure + O(formations²) for contact detection.
     * At 5000 units this is ~0.5–1ms on a modern CPU.
     */
    public precompute(): void {
        if (!this.enabled) return;

        // Peaceful / stress-peaceful: no combat forces needed.
        const peacefulStress = !!this.scene.stressTestConfig && !this.scene.stressTestConfig.enableEnemies;
        if (peacefulStress || this.scene.peacefulMode) {
            this.pressureGrid.clear();
            this.contactLines.length = 0;
            return;
        }

        const allUnits = this.scene.units.getChildren() as GameUnit[];

        // ── 1. Pressure grid ──────────────────────────────────────────
        // Count units per cell, then compute outward pressure from density gradients.
        this.buildPressureGrid(allUnits);

        // ── 2. Contact lines ──────────────────────────────────────────
        // Detect opposing formation pairs and compute contact boundaries.
        this.detectContactLines(allUnits);
    }

    // ─── Pressure ────────────────────────────────────────────────────────

    /**
     * Build the pressure grid: for each occupied cell, compute the average
     * outward pressure direction (away from cell centroid) and force magnitude
     * based on density².
     *
     * We approximate "outward" by comparing this cell's density to the average
     * of its 8 neighbors. High-density cells surrounded by lower-density cells
     * get strong outward pressure; uniformly dense areas get less (no gradient).
     */
    private buildPressureGrid(units: GameUnit[]): void {
        this.pressureGrid.clear();

        // Phase 1: count density + accumulate centroid per cell.
        const cellData = new Map<string, { count: number; sx: number; sy: number }>();

        for (let i = 0; i < units.length; i++) {
            const unit = units[i];
            // Only military units contribute to combat pressure.
            if (this.isCivilian(unit)) continue;

            const key = unit.getData('spatialKey') as string;
            if (!key) continue;

            let data = cellData.get(key);
            if (!data) {
                data = { count: 0, sx: 0, sy: 0 };
                cellData.set(key, data);
            }
            data.count++;
            data.sx += unit.x;
            data.sy += unit.y;
        }

        // Phase 2: compute pressure from density gradient.
        // For each occupied cell, check 8 neighbors. Pressure direction = away
        // from the weighted neighbor centroid. Force = (localDensity - avgNeighborDensity)².
        for (const [key, data] of cellData) {
            const [cx, cy] = key.split(',').map(Number);

            let neighborCount = 0;
            let neighborDensitySum = 0;
            // Gradient vector: points from high density → low density.
            let gx = 0;
            let gy = 0;

            for (let dx = -1; dx <= 1; dx++) {
                for (let dy = -1; dy <= 1; dy++) {
                    if (dx === 0 && dy === 0) continue;
                    const nKey = `${cx + dx},${cy + dy}`;
                    const nData = cellData.get(nKey);
                    if (nData) {
                        neighborCount++;
                        neighborDensitySum += nData.count;
                        // Gradient: this density minus neighbor density, weighted by direction.
                        const diff = data.count - nData.count;
                        gx += dx * diff;
                        gy += dy * diff;
                    }
                }
            }

            const avgNeighborDensity = neighborCount > 0 ? neighborDensitySum / neighborCount : 0;
            const densityExcess = Math.max(0, data.count - avgNeighborDensity);

            // Force scales with density excess² (quadratic = compression feel).
            // Normalize by PRESSURE_DENSITY_MAX so a cell with 8 excess units = max force.
            const normalizedExcess = Math.min(1, densityExcess / PRESSURE_DENSITY_MAX);
            const force = Math.pow(normalizedExcess, PRESSURE_CURVE) * PRESSURE_FORCE_MAX;

            if (force < 1) continue; // skip negligible pressure

            // Pressure direction: along the density gradient (high → low).
            // If no gradient (uniform density), use the cell centroid → unit direction.
            let dirX: number;
            let dirY: number;

            const gMag = Math.sqrt(gx * gx + gy * gy);
            if (gMag > 0.001) {
                dirX = gx / gMag;
                dirY = gy / gMag;
            } else {
                // Uniform density: push outward from cell centroid.
                const centroidX = data.sx / data.count;
                const centroidY = data.sy / data.count;
                const cellCenterX = cx * CELL_SIZE + CELL_SIZE / 2;
                const cellCenterY = cy * CELL_SIZE + CELL_SIZE / 2;
                dirX = cellCenterX - centroidX;
                dirY = cellCenterY - centroidY;
                const dMag = Math.sqrt(dirX * dirX + dirY * dirY);
                if (dMag > 0.001) {
                    dirX /= dMag;
                    dirY /= dMag;
                } else {
                    // Degenerate: random-ish stable direction based on cell coords.
                    dirX = Math.cos(cx * 0.7 + cy * 1.3);
                    dirY = Math.sin(cx * 0.7 + cy * 1.3);
                }
            }

            this.pressureGrid.set(key, {
                dirX,
                dirY,
                force,
                density: data.count,
            });
        }
    }

    /**
     * Get the pressure force for a unit at a given cell key.
     * Returns null if no pressure (cell empty or negligible).
     */
    public getPressure(cellKey: string): CellPressure | null {
        return this.pressureGrid.get(cellKey) ?? null;
    }

    // ─── Contact Lines ───────────────────────────────────────────────────

    /**
     * Detect contact lines between opposing formations.
     *
     * Strategy: group military units by (owner, cellKey) → centroid + count + AABB.
     * For each friendly formation, check AABB gap to enemy formations. If
     * front-to-front gap < CONTACT_RANGE (overlapping or near-engaged fronts),
     * compute a contact line at the gap midpoint (not centroid midpoint).
     * Enables contact line ripple at real combat boundaries.
     *
     * This is O(cells × neighbor_cells) which is tiny — cells are 150px and
     * only occupied cells are iterated.
     */
    private detectContactLines(units: GameUnit[]): void {
        this.contactLines.length = 0;

        // Group military units by (owner, cellKey) → centroid + count + AABB.
        // The AABB (min/max per axis) lets us measure FRONT-TO-FRONT proximity:
        // formation centroids stay 100px+ apart even at full engagement (fronts
        // stop at attack range), so centroid distance never registers contact.
        const formations = new Map<string, {
            owner: number; cx: number; cy: number; count: number; sx: number; sy: number;
            minX: number; maxX: number; minY: number; maxY: number;
        }>();

        for (let i = 0; i < units.length; i++) {
            const unit = units[i];
            if (this.isCivilian(unit)) continue;

            const owner = unit.getData('owner') as number;
            if (owner < 0) continue; // skip neutral

            const key = unit.getData('spatialKey') as string;
            if (!key) continue;

            const fKey = `${owner}|${key}`;
            let f = formations.get(fKey);
            if (!f) {
                const [cx, cy] = key.split(',').map(Number);
                f = {
                    owner, cx, cy, count: 0, sx: 0, sy: 0,
                    minX: Infinity, maxX: -Infinity, minY: Infinity, maxY: -Infinity,
                };
                formations.set(fKey, f);
            }
            f.count++;
            f.sx += unit.x;
            f.sy += unit.y;
            if (unit.x < f.minX) f.minX = unit.x;
            if (unit.x > f.maxX) f.maxX = unit.x;
            if (unit.y < f.minY) f.minY = unit.y;
            if (unit.y > f.maxY) f.maxY = unit.y;
        }

        // For each friendly formation, find nearby enemy formations.
        for (const [, friendly] of formations) {
            const friendlyX = friendly.sx / friendly.count;
            const friendlyY = friendly.sy / friendly.count;

            // Check neighboring cells (within CONTACT_RANGE / CELL_SIZE cells).
            const cellReach = Math.ceil(CONTACT_RANGE / CELL_SIZE);

            for (let dx = -cellReach; dx <= cellReach; dx++) {
                for (let dy = -cellReach; dy <= cellReach; dy++) {
                    const enemyCx = friendly.cx + dx;
                    const enemyCy = friendly.cy + dy;
                    const enemyKey = `${1 - friendly.owner}|${enemyCx},${enemyCy}`;
                    const enemy = formations.get(enemyKey);
                    if (!enemy) continue;

                    // Front-to-front gap: axis-separated AABB distance.
                    // Overlapping boxes (engaged fronts) → 0; far apart → px gap.
                    const gapX = Math.max(0, Math.max(friendly.minX, enemy.minX) - Math.min(friendly.maxX, enemy.maxX));
                    const gapY = Math.max(0, Math.max(friendly.minY, enemy.minY) - Math.min(friendly.maxY, enemy.maxY));
                    const gap = Math.sqrt(gapX * gapX + gapY * gapY);

                    if (gap > CONTACT_RANGE) continue;

                    // Contact strength: 1.0 at full front contact, 0.0 at CONTACT_RANGE.
                    const strength = Math.min(1, 1 - gap / CONTACT_RANGE);

                    // Normal: friendly → enemy (from centroids; fall back to cell centers).
                    const enemyX = enemy.sx / enemy.count;
                    const enemyY = enemy.sy / enemy.count;
                    const distX = enemyX - friendlyX;
                    const distY = enemyY - friendlyY;
                    let nx: number;
                    let ny: number;
                    const dist = Math.sqrt(distX * distX + distY * distY);
                    if (dist > 0.001) {
                        nx = distX / dist;
                        ny = distY / dist;
                    } else {
                        const ddx = enemy.cx - friendly.cx;
                        const ddy = enemy.cy - friendly.cy;
                        const dd = Math.sqrt(ddx * ddx + ddy * ddy);
                        if (dd > 0.001) {
                            nx = ddx / dd;
                            ny = ddy / dd;
                        } else {
                            nx = 1;
                            ny = 0;
                        }
                    }

                    // Tangent: perpendicular to normal (lateral flow direction).
                    // Pick the tangent that creates a more natural flow (alternate per cell parity).
                    const parity = ((friendly.cx + friendly.cy) & 1) === 0 ? 1 : -1;
                    const tx = -ny * parity;
                    const ty = nx * parity;

                    // Contact boundary: midpoint of the front gap/overlap where the
                    // two blobs actually face each other (not the centroid midpoint,
                    // which sits deep inside each formation at real engagements).
                    const contactX = (Math.max(friendly.minX, enemy.minX) + Math.min(friendly.maxX, enemy.maxX)) / 2;
                    const contactY = (Math.max(friendly.minY, enemy.minY) + Math.min(friendly.maxY, enemy.maxY)) / 2;

                    this.contactLines.push({
                        x: contactX,
                        y: contactY,
                        nx,
                        ny,
                        tx,
                        ty,
                        strength,
                        owner: friendly.owner,
                    });
                }
            }
        }
    }


    /**
     * Get the total contact force for a unit at position (x, y) with given owner.
     * Sums all contact lines within CONTACT_SAMPLE_RADIUS.
     * Returns { backwardX, backwardY, lateralX, lateralY } force components.
     */
    public getContactForce(
        x: number,
        y: number,
        owner: number
    ): { bx: number; by: number; lx: number; ly: number } {
        let bx = 0;
        let by = 0;
        let lx = 0;
        let ly = 0;

        const rangeSq = CONTACT_SAMPLE_RADIUS * CONTACT_SAMPLE_RADIUS;

        for (let i = 0; i < this.contactLines.length; i++) {
            const cl = this.contactLines[i];
            if (cl.owner !== owner) continue;

            const dx = x - cl.x;
            const dy = y - cl.y;
            const distSq = dx * dx + dy * dy;
            if (distSq > rangeSq) continue;

            // Falloff: 1.0 at center, 0.0 at edge.
            const dist = Math.sqrt(distSq);
            const falloff = 1 - dist / CONTACT_SAMPLE_RADIUS;
            const force = cl.strength * falloff;

            // Backward push: away from enemy (along normal, reversed = toward friendly).
            // Normal points friendly→enemy, so backward = -normal.
            bx -= cl.nx * CONTACT_BACKWARD_FORCE * force;
            by -= cl.ny * CONTACT_BACKWARD_FORCE * force;

            // Lateral flow: along tangent.
            lx += cl.tx * CONTACT_LATERAL_FORCE * force;
            ly += cl.ty * CONTACT_LATERAL_FORCE * force;
        }

        return { bx, by, lx, ly };
    }

    // ─── Velocity Alignment ──────────────────────────────────────────────

    /**
     * Compute velocity alignment for a unit using SpatialHash neighbors.
     * Called per-unit in UnitSystem's bucket pass to avoid a second O(n) sweep.
     *
     * Returns the target average velocity { x, y } and neighbor count,
     * or null if not enough neighbors.
     */
    public getAlignmentVelocity(
        unit: GameUnit
    ): { vx: number; vy: number; count: number } | null {
        const spatialHash = this.scene.unitSpatialHash;
        if (!spatialHash) return null;

        const neighbors = spatialHash.query(unit.x, unit.y, ALIGN_RADIUS);
        if (neighbors.length < ALIGN_MIN_NEIGHBORS) return null;

        let avgVx = 0;
        let avgVy = 0;
        let count = 0;

        for (let i = 0; i < neighbors.length; i++) {
            const other = neighbors[i] as GameUnit;
            if (other === unit) continue;
            if (this.isCivilian(other)) continue;

            const body = other.body as Phaser.Physics.Arcade.Body;
            if (!body) continue;

            avgVx += body.velocity.x;
            avgVy += body.velocity.y;
            count++;
        }

        if (count < ALIGN_MIN_NEIGHBORS) return null;

        return {
            vx: avgVx / count,
            vy: avgVy / count,
            count,
        };
    }

    /**
     * Apply velocity alignment to a unit. Interpolates toward neighbor average.
     * Alignment strength scales with neighbor count (more neighbors = stronger alignment).
     */
    public applyAlignment(unit: GameUnit): void {
        const alignment = this.getAlignmentVelocity(unit);
        if (!alignment) return;

        const body = unit.body as Phaser.Physics.Arcade.Body;
        if (!body) return;

        // Strength scales with neighbor count, capped at ALIGN_STRENGTH.
        const strength = Math.min(ALIGN_STRENGTH, alignment.count * 0.03);

        body.velocity.x = Phaser.Math.Linear(body.velocity.x, alignment.vx, strength);
        body.velocity.y = Phaser.Math.Linear(body.velocity.y, alignment.vy, strength);
    }

    // ─── Helpers ─────────────────────────────────────────────────────────

    /**
     * Check if a unit is civilian (villager/animal) and should be excluded from combat fluid.
     */
    private isCivilian(unit: GameUnit): boolean {
        return unit.unitType === UnitType.VILLAGER || unit.unitType === UnitType.ANIMAL;
    }

    /**
     * Get the count of active contact lines (for debugging/profiling).
     */
    public get contactLineCount(): number {
        return this.contactLines.length;
    }

    /**
     * Get the count of active pressure cells (for debugging/profiling).
     */
    public get pressureCellCount(): number {
        return this.pressureGrid.size;
    }

    // ─── Lifecycle ───────────────────────────────────────────────────────

    public destroy(): void {
        this.pressureGrid.clear();
        this.contactLines.length = 0;
    }
}

import Phaser from 'phaser';
import { MainScene } from '../MainScene';
import { UnitType, UnitState, FormationType, UnitStance, GameUnit, DamageType, DamageProfile, ArmorProfile, UnitAbility, BuildingType } from '../../types';
import { UNIT_SPEED, UNIT_STATS, UNIT_VISION, FORMATION_BONUSES, STANCE_TETHER_RADIUS, computeDamage, scaleDamageProfile, FACTION_BONUSES, TERRAIN_CONFIG, ABILITY_CONFIG, UNIT_ABILITIES, WALL_DEFENSE_BONUS, WALL_MELEE_PENALTY, WALL_PROXIMITY_RADIUS, RAM_VS_WALL_MULTIPLIER, SEP_COMBAT, CHARGE_IMPULSE, CHARGE_IMPULSE_DURATION_MS } from '../../constants';
import { toIso, toIsoElev } from '../utils/iso';
import { SoldierState } from './SquadSystem';
import { FormationSystem } from './FormationSystem';
import {
  findResumePathStep,
  shouldRepathChase,
  stalePathAction,
  pathEndNearTarget,
} from '../utils/combatPath';

/**
 * UnitSystem - Optimized for Annihilation-scale (thousands+ units).
 * 
 * Key optimizations:
 * - SpatialHash for O(1) neighbor queries instead of O(n²) iteration
 * - Bucket-based update scheduling: units spread across frames
 * - Scan throttling: combat units scan every 16 ticks, non-combat less frequently
 * - Simplified distant-unit logic (LOD for game logic)
 * - Batch path recalculation using spatial coherence
 */

const SCAN_INTERVAL_COMBAT = 500;   // ms between target scans for combat units
const _SCAN_INTERVAL_IDLE = 1000;     // ms between scans for idle units
const _PATH_RECALC_INTERVAL = 2000;   // ms between path recalculations
const SEPARATION_INTERVAL = 3;       // frames between separation checks
const STALE_PATH_LIFETIME = 5000;    // ms before a path is considered stale

/** All trainable military unit types — used for combat eligibility, targeting, selection, path viz. */
const COMBAT_UNIT_TYPES: UnitType[] = [
    UnitType.PIKESMAN, UnitType.ARCHER, UnitType.CAVALRY, UnitType.LEGION,
    UnitType.SLINGER, UnitType.AXEMAN, UnitType.HOPLITE, UnitType.CHARIOT, UnitType.RAM,
];
const FLOW_FIELD_THRESHOLD = 12;     // min units to trigger flow field instead of individual paths
const FLOW_STEER_INTERVAL = 80;    // ms between flow direction updates per unit
const MAX_ENGAGE_PER_TARGET = 3;    // max friendly units engaging the same enemy before spread kicks in

interface StressEmitter extends Phaser.GameObjects.GameObject {
    start?: () => void;
    stop?: () => void;
    setPosition?: (x: number, y: number) => void;
    setVisible?: (visible: boolean) => StressEmitter;
    setDepth?: (depth: number) => StressEmitter;
}

interface StressProjectile {
    arrow: Phaser.GameObjects.Rectangle;
    emitter: StressEmitter;

    originX: number;
    originY: number;
    targetX: number;
    targetY: number;

    // Quadratic bezier points in iso-screen space (2D)
    p0x: number; p0y: number;
    p1x: number; p1y: number;
    p2x: number; p2y: number;

    startAt: number; // ms in simulation time
    duration: number; // ms

    dmg: number;
    takeDamage: (amt: number) => void;

    started: boolean;
    finished: boolean;
}

interface StressLunge {
    visual: Phaser.GameObjects.GameObject;
    startX: number;
    startY: number;
    endX: number;
    endY: number;

    startAt: number;
    duration: number;
    unitRef: GameUnit;
}

export class UnitSystem {
    private scene: MainScene;
    private pathGraphics: Phaser.GameObjects.Graphics;
    private debugGraphics: Phaser.GameObjects.Graphics;

    private activeStressProjectiles: StressProjectile[] = [];
    private activeStressLunges: StressLunge[] = [];

    private arrowPool: Phaser.GameObjects.Rectangle[] = [];
    private emitterPool: StressEmitter[] = [];

    private projectilePoolMax: number = 600;
    private lungeDurationMs: number = 100;

    public currentFormation: FormationType = FormationType.BOX;
    public currentStance: UnitStance = UnitStance.HOLD;

    // Per-frame update budget
    private maxUnitsPerFrame: number = 300;
    private updateIndex: number = 0;
    private separationFrame: number = 0;

    constructor(scene: MainScene) {
        this.scene = scene;
        this.pathGraphics = this.scene.add.graphics().setDepth(-4000);
        this.debugGraphics = this.scene.add.graphics().setDepth(100000);
    }

    // ─── Main Update ──────────────────────────────────────────────────────
    public update(time: number, _delta: number): void {
        const allUnits = this.scene.units.getChildren() as GameUnit[];
        const unitCount = allUnits.length;
        if (unitCount === 0) return;


        if (this.scene.stressTestConfig) {
            this.updateStressProjectiles(time);
            this.updateStressLunges(time);
        }
        // Active stress benchmark: orbital paths ONLY in peaceful mode (no combat).
        // In combat stress mode, units use normal physics/pathfinding/liquid steering.
        if (this.scene.stressTestConfig && !this.scene.stressTestConfig.enableEnemies) {
            const centerX = this.scene.mapWidth * 0.5;
            const centerY = this.scene.mapHeight * 0.5;
            const phaseTime = time * 0.00035;
            for (let i = 0; i < unitCount; i++) {
                const unit = allUnits[i];
                const body = unit.body as Phaser.Physics.Arcade.Body | null;
                if (body && !body.enable) continue;
                const phase = (unit.getData('stressPhase') as number | undefined) ?? (i * 0.017);
                if (unit.getData('stressPhase') === undefined) {
                    unit.setData('stressPhase', phase);
                }
                const radius = 260 + (i % 23) * 2;
                const x = centerX + Math.cos(phaseTime + phase) * radius;
                const y = centerY + Math.sin(phaseTime + phase) * radius * 0.62;
                unit.setPosition(x, y);
            }
        }

        if (this.scene.stressTestConfig && !this.scene.stressTestConfig.enableEnemies) {
            // Peaceful stress units are stationary: skip path queue + mass flow pass.
        } else {
            // Process pathfinding queue (throttle for large counts)
            if (unitCount < 1000) {
                this.scene.pathfinder.processQueue();
            } else {
                this.scene.pathfinder.processQueueBudgeted(100); // cap per frame
            }

            // Flow field steering is O(1) per unit — throttle makes expensive part rare
            for (let i = 0; i < unitCount; i++) {
                const unit = allUnits[i];
                if (!unit || !unit.scene) continue;
                if (unit.flowTarget) {
                    this.moveAlongFlowField(unit, time);
                }
            }
        }

        // Adaptive per-frame budget: scale with total units but cap sanity
        const budget = this.scene.stressTestConfig ? Math.min(600, unitCount) : this.maxUnitsPerFrame;
        const bucketSize = Math.max(1, Math.ceil(unitCount / Math.ceil(unitCount / budget)));
        const start = this.updateIndex;
        const end = Math.min(start + bucketSize, unitCount);

        const peacefulStress = !!this.scene.stressTestConfig && !this.scene.stressTestConfig.enableEnemies;
        if (!peacefulStress) {
            for (let i = start; i < end; i++) {
                const unit = allUnits[i];
                if (!unit) continue;
                this.updateUnitLogicTimed(unit, time);
                this.applyLiquidSteering(unit, time);
            }
        }

        // Advance or wrap bucket index
        this.updateIndex += bucketSize;
        if (this.updateIndex >= unitCount) {
            this.updateIndex = 0;
        }

        if (!peacefulStress) {
            // Dynamic separation interval: less frequent for dense groups
            const sepInterval = unitCount > 2000 ? 60 : (unitCount > 1000 ? 30 : (unitCount > 500 ? 15 : SEPARATION_INTERVAL));
            this.separationFrame++;
            if (this.separationFrame >= sepInterval) {
                this.separationFrame = 0;
                this.applySeparation();
            }
        }

        // Path rendering: only for small groups (<500) or debug mode
        // Fix 1: Gate drawUnitPaths to prevent O(n) iteration waste
        if (!peacefulStress && (unitCount < 500 || this.scene.debugMode)) {
            this.drawUnitPaths(time);
        } else {
            this.pathGraphics.clear();
        }
        if (this.scene.debugMode) {
            this.drawDebugLines();
        } else {
            this.debugGraphics.clear();
        }
    }

    /**
     * Update a single unit's logic with time-based throttling.
     */
    private updateUnitLogicTimed(unit: GameUnit, time: number): void {
        const body = unit.body as Phaser.Physics.Arcade.Body;
        if (!body) return;

        // Skip villagers and animals (managed by their own systems)
        if (unit.unitType === UnitType.VILLAGER || unit.unitType === UnitType.ANIMAL) return;

        // Skip flow field units — handled in the synchronous mass pass above
        if (unit.flowTarget) return;

        // Failsafe: peaceful mode forces enemy units to stop
        if (this.scene.peacefulMode === true && unit.getData('owner') !== 0) {
            if (unit.state === UnitState.CHASING || unit.state === UnitState.ATTACKING) {
                unit.state = UnitState.IDLE;
                unit.target = null;
                body.setVelocity(0, 0);
            }
        }

        // Combat state handling

        if (unit.state === UnitState.CHASING || unit.state === UnitState.ATTACKING) {
            this.handleCombatState(unit, time);
        }
        // Path following
        else if (unit.path && unit.path.length > 0) {
            this.moveAlongPath(unit);
        }
        // Idle: auto-target scan (throttled)
        else if (unit.state === UnitState.IDLE) {
            this.scanForTargets(unit, time);
        }
        // Fallback: stop any residual velocity
        else {
            if (body.velocity.length() > 0) body.setVelocity(0, 0);
        }
    }

    // ─── Separation (O(n) using SpatialHash) ──────────────────────────────
    private applySeparation(): void {
        const units = this.scene.units.getChildren() as GameUnit[];
        if (units.length < 2) return;

        // Use SpatialHash for neighbor queries
        const queryRadius = 20;
        const spatialHash = this.scene.unitSpatialHash;

if (spatialHash) {
            for (const unit of units) {
                // Skip flow field units — crowd steering handles spacing
                if (unit.flowTarget) continue;

                // Skip IDLE units — they should not be pushed by separation
                if (unit.state === UnitState.IDLE) continue;

                const body = unit.body as Phaser.Physics.Arcade.Body;
                if (!body || (body.velocity.x * body.velocity.x + body.velocity.y * body.velocity.y) < 1) continue;

                const neighbors = spatialHash.query(unit.x, unit.y, queryRadius);
                for (const other of neighbors) {
                    if (other === unit) continue;
                    const otherBody = other.body as Phaser.Physics.Arcade.Body;
                    if (!otherBody) continue;

                    const dx = unit.x - other.x;
                    const dy = unit.y - other.y;
                    const distSq = dx * dx + dy * dy;
                    if (distSq < 324 && distSq > 0.0001) {
                        const dist = Math.sqrt(distSq);
                        // Combat units use reduced separation (SEP_COMBAT) so they cluster/dempet
                        // instead of maintaining boid spacing. Front-rank lock & flank wrap rely on this.
                        const isCombat = unit.state === UnitState.CHASING || unit.state === UnitState.ATTACKING;
                        const sepScale = isCombat ? SEP_COMBAT : 1.0;
                        const force = (18 - dist) * 0.8 * sepScale;
                        const nx = dx / dist;
                        const ny = dy / dist;
                        body.velocity.x += nx * force;
                        body.velocity.y += ny * force;
                        otherBody.velocity.x -= nx * force;
                        otherBody.velocity.y -= ny * force;
                    }
                }
            }
        } else {
            // Fallback: brute force for very small unit counts
            for (let i = 0; i < units.length; i++) {
                const unit = units[i];
                const body = unit.body as Phaser.Physics.Arcade.Body;
                if (!body || (body.velocity.x * body.velocity.x + body.velocity.y * body.velocity.y) < 1) continue;

                for (let j = i + 1; j < units.length; j++) {
                    const other = units[j];
                    const otherBody = other.body as Phaser.Physics.Arcade.Body;
                    if (!otherBody) continue;
                    const dx = unit.x - other.x;
                    const dy = unit.y - other.y;
                    const distSq = dx * dx + dy * dy;
                    if (distSq < 324 && distSq > 0.0001) {
                        const dist = Math.sqrt(distSq);
                        const isCombat = unit.state === UnitState.CHASING || unit.state === UnitState.ATTACKING;
                        const sepScale = isCombat ? SEP_COMBAT : 1.0;
                        const force = (18 - dist) * 0.8 * sepScale;
                        const nx = dx / dist;
                        const ny = dy / dist;
                        body.velocity.x += nx * force;
                        body.velocity.y += ny * force;
                        otherBody.velocity.x -= nx * force;
                        otherBody.velocity.y -= ny * force;
                    }
                }
            }
        }
    }


    // ─── Liquid Combat Steering ───────────────────────────────────────────
    /**
     * Apply fluid combat forces to a single unit: pressure + contact-line + velocity alignment.
     * Called inside the rotating bucket pass (update()) so every unit gets forces over time.
     * Skips civilians, flow-field units, and units without physics bodies.
     */
    private applyLiquidSteering(unit: GameUnit, _time: number): void {
        const liquidCombat = this.scene.liquidCombat;
        if (!liquidCombat || !liquidCombat.enabled) return;

        // Skip civilians (villagers, animals)
        if (unit.unitType === UnitType.VILLAGER || unit.unitType === UnitType.ANIMAL) return;

        // Skip IDLE units — they should not receive combat steering forces
        if (unit.state === UnitState.IDLE) return;

        // Skip flow-field units — mass steering already handles spacing for them
        if (unit.flowTarget) return;

        const body = unit.body as Phaser.Physics.Arcade.Body;
        if (!body || !body.enable) return;

        // Accumulate total combat force for visual deformation (per-soldier in renderSquad)
        let forceX = 0;
        let forceY = 0;

        // 1. Pressure force — outward push from dense cell
        const cellKey = unit.getData('spatialKey') as string;
        if (cellKey) {
            const pressure = liquidCombat.getPressure(cellKey);
            if (pressure && pressure.force > 0) {
                const px = pressure.dirX * pressure.force;
                const py = pressure.dirY * pressure.force;
                body.velocity.x += px;
                body.velocity.y += py;
                forceX += px;
                forceY += py;
            }
        }

        // 2. Contact-line force — backward push + lateral flow at enemy boundary
        const owner = unit.getData('owner') as number;
        if (owner >= 0) {
            const contact = liquidCombat.getContactForce(unit.x, unit.y, owner);
            if (contact.bx !== 0 || contact.by !== 0 || contact.lx !== 0 || contact.ly !== 0) {
                const cx = contact.bx + contact.lx;
                const cy = contact.by + contact.ly;
                body.velocity.x += cx;
                body.velocity.y += cy;
                forceX += cx;
                forceY += cy;
            }
        }

        // Store force for SquadSystem per-soldier deformation (scaled to px offset)
        // Divide by force scale to convert velocity-space force to visual displacement
        const DEFORMATION_SCALE = 0.15;
        unit.modifiedOffset = { x: forceX * DEFORMATION_SCALE, y: forceY * DEFORMATION_SCALE };

        // 3. Velocity alignment — smooth toward neighbor average (piggybacks on separation interval)
        // Only apply alignment on frames where separation runs, to avoid extra SpatialHash queries
        // We check the shared separationFrame counter
        if (this.separationFrame === 0) {
            liquidCombat.applyAlignment(unit);
        }

        // Cap velocity to prevent runaway acceleration
        const MAX_SPEED = 200;
        const vx = body.velocity.x;
        const vy = body.velocity.y;
        const speedSq = vx * vx + vy * vy;
        if (speedSq > MAX_SPEED * MAX_SPEED) {
            const scale = MAX_SPEED / Math.sqrt(speedSq);
            body.velocity.x = vx * scale;
            body.velocity.y = vy * scale;
        }
    }

    // ─── Movement Commands ─────────────────────────────────────────────────
    public commandMove(units: Phaser.GameObjects.GameObject[], target: Phaser.Math.Vector2, queue: boolean = false): void {
        // For large groups, compute one flow field instead of N individual paths
        if (units.length >= FLOW_FIELD_THRESHOLD && !queue) {
            this.commandMoveFlowField(units, target);
            return;
        }

        const spacing = 15;
        const groupOffsets = FormationSystem.getFormationOffsets(this.currentFormation, units.length, spacing);

        let rotationAngle = 0;
        if (this.currentFormation === FormationType.LINE || this.currentFormation === FormationType.WEDGE) {
            let sumX = 0, sumY = 0;
            for (const u of units) {
                const unit = u as Phaser.GameObjects.Image;
                sumX += unit.x;
                sumY += unit.y;
            }
            const avgX = sumX / units.length;
            const avgY = sumY / units.length;
            rotationAngle = Phaser.Math.Angle.Between(avgX, avgY, target.x, target.y) + Math.PI / 2;
        }

        for (let index = 0; index < units.length; index++) {
            const unit = units[index] as GameUnit;

            this.scene.squadSystem.applyFormation(unit, this.currentFormation);
            unit.setData('formation', this.currentFormation);

            const baseOffset = groupOffsets[index];
            const rotatedOffset = new Phaser.Math.Vector2(
                baseOffset.x * Math.cos(rotationAngle) - baseOffset.y * Math.sin(rotationAngle),
                baseOffset.x * Math.sin(rotationAngle) + baseOffset.y * Math.cos(rotationAngle)
            );

            const unitTarget = new Phaser.Math.Vector2(target.x + rotatedOffset.x, target.y + rotatedOffset.y);

            const startPos = (queue && unit.path && unit.path.length > 0)
                ? unit.path[unit.path.length - 1]
                : new Phaser.Math.Vector2(unit.x, unit.y);

            const path = this.scene.pathfinder.findPath(startPos, unitTarget);
            // Stay-put ([start] only) means no route — do not assign fake path
            if (path && path.length > 1) {
                if (queue && unit.path) {
                    unit.path = unit.path.concat(path);
                } else {
                    unit.path = path;
                    unit.pathStep = 0;
                    unit.pathCreatedAt = this.scene.gameTime;
                    unit.state = UnitState.IDLE;
                    unit.target = null;
                    (unit.body as Phaser.Physics.Arcade.Body).reset(unit.x, unit.y);
                    unit.setData('anchor', { x: target.x, y: target.y });
                }
            }

            // Per-unit path memory cleanup: cap path length for long queues
            if (unit.path && unit.path.length > 200) {
                unit.path = unit.path.slice(unit.pathStep);
                unit.pathStep = 0;
            }
        }

        // Visual feedback
        const iso = toIso(target.x, target.y);
        const color = queue ? 0xffff00 : 0xffffff;
        const circle = this.scene.add.circle(iso.x, iso.y, 5, color);
        circle.setScale(1, 0.5);
        circle.setDepth(iso.y);
        this.scene.tweens.add({
            targets: circle,
            scaleX: 0, scaleY: 0, alpha: 0,
            duration: 500,
            onComplete: () => circle.destroy()
        });
    }

    /**
     * Mass movement using flow fields.
     * Computes one flow field for the target, assigns it to all units.
     */
    private commandMoveFlowField(units: Phaser.GameObjects.GameObject[], target: Phaser.Math.Vector2): void {
        const flowField = this.scene.pathfinder.generateFlowField(target.x, target.y);
        const spacing = 15;
        const groupOffsets = FormationSystem.getFormationOffsets(this.currentFormation, units.length, spacing);

        let rotationAngle = 0;
        if (this.currentFormation === FormationType.LINE || this.currentFormation === FormationType.WEDGE) {
            let sumX = 0, sumY = 0;
            for (const u of units) {
                const img = u as Phaser.GameObjects.Image;
                sumX += img.x;
                sumY += img.y;
            }
            const avgX = sumX / units.length;
            const avgY = sumY / units.length;
            rotationAngle = Phaser.Math.Angle.Between(avgX, avgY, target.x, target.y) + Math.PI / 2;
        }

        for (let index = 0; index < units.length; index++) {
            const unit = units[index] as GameUnit;

            this.scene.squadSystem.applyFormation(unit, this.currentFormation);
            unit.setData('formation', this.currentFormation);

            const baseOffset = groupOffsets[index];
            const rotatedOffset = new Phaser.Math.Vector2(
                baseOffset.x * Math.cos(rotationAngle) - baseOffset.y * Math.sin(rotationAngle),
                baseOffset.x * Math.sin(rotationAngle) + baseOffset.y * Math.cos(rotationAngle)
            );

            unit.flowTarget = { x: target.x + rotatedOffset.x, y: target.y + rotatedOffset.y };
            unit.path = null;
            unit.state = UnitState.IDLE;
            unit.target = null;
            unit.pathCreatedAt = this.scene.gameTime;
            unit.setData('_lastFlowSteer', 0);
            unit.setData('_flowField', flowField);
            (unit.body as Phaser.Physics.Arcade.Body).reset(unit.x, unit.y);
            unit.setData('anchor', { x: target.x, y: target.y });
        }

        const iso = toIso(target.x, target.y);
        const circle = this.scene.add.circle(iso.x, iso.y, 5, 0xffffff);
        circle.setScale(1, 0.5);
        circle.setDepth(iso.y);
        this.scene.tweens.add({
            targets: circle,
            scaleX: 0, scaleY: 0, alpha: 0,
            duration: 500,
            onComplete: () => circle.destroy()
        });
    }

    /**
     * Steer unit using cached flow field (O(1) per unit per steer interval).
     */
    private moveAlongFlowField(unit: GameUnit, _time: number): void {
        if (!unit.flowTarget) return;
        // Shield Wall: immobile
        if (unit.getData('shieldWall')) {
            const body = unit.body as Phaser.Physics.Arcade.Body;
            if (body) body.setVelocity(0, 0);
            return;
        }

        const flowField = unit.getData('_flowField') as { dirX: Float64Array; dirY: Float64Array; cols: number; rows: number } | undefined;
        if (!flowField) return;

        const dx = unit.x - unit.flowTarget.x;
        const dy = unit.y - unit.flowTarget.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        // Arrived at destination
        if (dist < 8) {
            const body = unit.body as Phaser.Physics.Arcade.Body;
            if (body) {
                body.setVelocity(0, 0);
                // Fully disable physics body for stationary units in stress test
                // This prevents Arcade physics from processing idle bodies (massive saving)
                if (this.scene.stressTestConfig) {
                    body.enable = false;
                }
            }
            unit.flowTarget = undefined;
            unit.setData('_flowField', undefined);
            return;
        }

        // Re-enable body if it was disabled (unit has started moving again)
        const body = unit.body as Phaser.Physics.Arcade.Body;
        if (body && !body.enable) body.enable = true;

        const lastSteer = unit.getData('_lastFlowSteer') as number || 0;
        if (this.scene.time.now - lastSteer < FLOW_STEER_INTERVAL) return;
        unit.setData('_lastFlowSteer', this.scene.time.now);

        const dir = this.scene.pathfinder.getFlowDirection(flowField, unit.x, unit.y);

        const baseSpeed = UNIT_SPEED[unit.unitType as UnitType] || 100;
        const formation = unit.getData('formation') as FormationType || FormationType.BOX;
        const multiplier = FORMATION_BONUSES[formation]?.speed || 1.0;
        const moveMult = this.scene.researchManager?.getSnapshot(unit.getData('owner') as number).movementSpeedMult ?? 1;
        const speed = baseSpeed * multiplier * moveMult;

        if (!dir || (dir.x === 0 && dir.y === 0)) {
            // No flow (on water/blocked or field hole) — stop; never straight-line through water
            if (body) body.setVelocity(0, 0);
            return;
        }

        // Blend flow (70%) + direct bias (30%); zero bias if it points into blocked/water
        const toTargetLen = dist;
        let biasX = 0;
        let biasY = 0;
        if (toTargetLen > 1) {
            biasX = -dx / toTargetLen;
            biasY = -dy / toTargetLen;
            if (this.scene.pathfinder.isBlocked(unit.x + biasX * 24, unit.y + biasY * 24)) {
                biasX = 0;
                biasY = 0;
            }
        }
        const blendX = dir.x * 0.7 + biasX * 0.3;
        const blendY = dir.y * 0.7 + biasY * 0.3;
        const blendLen = Math.sqrt(blendX * blendX + blendY * blendY);

        if (body && blendLen > 0.001) {
            body.setVelocity((blendX / blendLen) * speed, (blendY / blendLen) * speed);
        }
    }

    public commandFollowPath(units: Phaser.GameObjects.GameObject[], pathPoints: Phaser.Math.Vector2[], queue: boolean = false): void {
        if (pathPoints.length < 2) return;

        for (const unitObj of units) {
            const unit = unitObj as GameUnit;
            let fullPath: Phaser.Math.Vector2[] = [];

            const startPos = (queue && unit.path && unit.path.length > 0)
                ? unit.path[unit.path.length - 1]
                : new Phaser.Math.Vector2(unit.x, unit.y);

            const startPath = this.scene.pathfinder.findPath(startPos, pathPoints[0]);
            // Stay-put ([start] only) means no route — seed with current pos only
            if (startPath && startPath.length > 1) {
                fullPath = startPath;
            } else {
                fullPath = [new Phaser.Math.Vector2(startPos.x, startPos.y)];
            }

            for (let i = 0; i < pathPoints.length - 1; i++) {
                const segment = this.scene.pathfinder.findPath(pathPoints[i], pathPoints[i + 1]);
                if (segment && segment.length > 1) {
                    const lastPoint = fullPath[fullPath.length - 1];
                    const startIdx = (lastPoint && Phaser.Math.Distance.Between(lastPoint.x, lastPoint.y, segment[0].x, segment[0].y) < 2) ? 1 : 0;
                    for (let j = startIdx; j < segment.length; j++) {
                        fullPath.push(segment[j]);
                    }
                }
            }

            if (fullPath.length > 0) {
                if (queue && unit.path) {
                    unit.path = unit.path.concat(fullPath);
                } else {
                    unit.path = fullPath;
                    unit.pathStep = 0;
                    unit.pathCreatedAt = this.scene.gameTime;
                    unit.state = UnitState.IDLE;
                    unit.target = null;
                    (unit.body as Phaser.Physics.Arcade.Body).reset(unit.x, unit.y);
                }
            }

            // Cap path length
            if (unit.path && unit.path.length > 200) {
                unit.path = unit.path.slice(unit.pathStep);
                unit.pathStep = 0;
            }
        }

        // Visual feedback at destination
        const lastPoint = pathPoints[pathPoints.length - 1];
        const iso = toIso(lastPoint.x, lastPoint.y);
        const color = queue ? 0x00ffff : 0x00ff00;
        const circle = this.scene.add.circle(iso.x, iso.y, 5, color);
        circle.setScale(1, 0.5);
        circle.setDepth(iso.y);
        this.scene.tweens.add({
            targets: circle,
            scaleX: 0, scaleY: 0, alpha: 0,
            duration: 500,
            onComplete: () => circle.destroy()
        });
    }

    // ─── Stance / Formation ───────────────────────────────────────────────
    public setStance(stance: UnitStance): void {
        this.currentStance = stance;
        const selected = this.scene.inputManager.selectedUnits;
        if (selected && selected.length > 0) {
            for (const obj of selected) {
                const u = obj as GameUnit;
                u.setData('stance', stance);
                if (stance === UnitStance.HOLD && u.state === UnitState.CHASING) {
                    u.state = UnitState.IDLE;
                    u.target = null;
                    const body = u.body as Phaser.Physics.Arcade.Body;
                    if (body) body.setVelocity(0, 0);
                }
                u.setData('anchor', { x: u.x, y: u.y });
            }
        }
    }

    public setFormation(type: FormationType): void {
        this.currentFormation = type;
    }

    // ─── Attack Commands ───────────────────────────────────────────────────
    public commandAttack(units: Phaser.GameObjects.GameObject[], target: Phaser.GameObjects.GameObject): void {
        for (const unitObj of units) {
            const unit = unitObj as GameUnit;

            if (this.scene.peacefulMode && unit.getData('owner') !== 0) {
                if (this.scene.debugMode) {
                    const iso = toIso(unit.x, unit.y);
                    const x = this.scene.add.text(iso.x, iso.y, "X", { color: '#ff0000', fontSize: '20px' });
                    x.setOrigin(0.5);
                    this.scene.tweens.add({ targets: x, y: iso.y - 20, alpha: 0, duration: 500, onComplete: () => x.destroy() });
                }
                return;
            }


            if (COMBAT_UNIT_TYPES.includes(unit.unitType)) {
                unit.target = target;
                unit.state = UnitState.CHASING;
                unit.path = null;
                unit.flowTarget = undefined;
                unit.setData('_flowField', undefined);
                unit.setData('explicitTarget', true);
                unit.setData('_lastPathRecalc', 0);
                unit.setData('_chaseTargetPos', undefined);
                (unit.body as Phaser.Physics.Arcade.Body).reset(unit.x, unit.y);
            }
        }

        // Visual Feedback
        const targetVisual = (target as GameUnit).visual;
        if (targetVisual) {
            this.scene.tweens.add({
                targets: targetVisual,
                alpha: 0.5, yoyo: true, duration: 100, repeat: 2
            });
        }
    }

    // ─── Target Scanning (SpatialHash optimized, spread targeting) ───────
    /** Per-frame engagement cache: enemy → number of friendly units targeting it. */
    private _engageCache: Map<Phaser.GameObjects.GameObject, number> = new Map();
    private _engageCacheFrame = -1;

    /**
     * Build (or reuse) a per-frame map of enemy → how many of `owner`'s units are targeting it.
     * Cached per frame so it's O(n) per frame, not O(n²) per scan call.
     */
    private _buildEngagementMap(owner: number): Map<Phaser.GameObjects.GameObject, number> {
        const frame = this.scene.game.loop.frame;
        if (this._engageCacheFrame === frame) return this._engageCache;

        this._engageCache.clear();
        const children = this.scene.units.getChildren();
        for (let i = 0, len = children.length; i < len; i++) {
            const u = children[i] as GameUnit;
            if (u.getData('owner') !== owner) continue;
            if (u.getData('hp') <= 0) continue;
            const tgt = u.target;
            if (!tgt) continue;
            this._engageCache.set(tgt, (this._engageCache.get(tgt) || 0) + 1);
        }
        this._engageCacheFrame = frame;
        return this._engageCache;
    }

    private scanForTargets(unit: GameUnit, _time: number): void {
        // Throttle: only scan periodically (~every 500ms)
        const lastScan = unit.getData('_lastScan') as number || 0;
        if (this.scene.time.now - lastScan < SCAN_INTERVAL_COMBAT) return;
        unit.setData('_lastScan', this.scene.time.now);

        const isCombatUnit = COMBAT_UNIT_TYPES.includes(unit.unitType);
        if (!isCombatUnit) return;

        const stance = unit.getData('stance') as UnitStance || UnitStance.DEFENSIVE;
        const visionRange = UNIT_VISION[unit.unitType] || 250;
        const myOwner = unit.getData('owner') as number;
        // Siege units (RAM) only target buildings, not units
        const isSiegeUnit = unit.unitType === UnitType.RAM;

        let closest: Phaser.GameObjects.GameObject | null = null;
        let closestDist = visionRange;

        // Siege units skip unit targeting — go straight to buildings
        if (!isSiegeUnit) {
            const spatialHash = this.scene.unitSpatialHash;
            let candidates: Phaser.GameObjects.GameObject[];

            if (spatialHash) {
                candidates = spatialHash.query(unit.x, unit.y, visionRange);
            } else {
                candidates = this.scene.units.getChildren();
            }

            const engageCount = this._buildEngagementMap(myOwner);

            let best: Phaser.GameObjects.GameObject | null = null;
            let bestDist = visionRange;
            let fallback: Phaser.GameObjects.GameObject | null = null;
            let fallbackDist = visionRange;

            for (const other of candidates) {
                if (other === unit) continue;
                const otherOwner = other.getData('owner') as number;
                if (otherOwner === myOwner) continue;
                const hp = other.getData('hp') as number;
                if (hp <= 0) continue;

                const otherType = other.getData('unitType') || (other as GameUnit).unitType;
                if (otherType === UnitType.ANIMAL) continue;

                const otherImg = other as Phaser.GameObjects.Image;
                const dx = unit.x - otherImg.x;
                const dy = unit.y - otherImg.y;
                const dist = Math.sqrt(dx * dx + dy * dy);

                if (dist < fallbackDist) {
                    fallback = other;
                    fallbackDist = dist;
                }
                if (dist < bestDist && (engageCount.get(other) || 0) < MAX_ENGAGE_PER_TARGET) {
                    best = other;
                    bestDist = dist;
                }
            }

            closest = best || fallback;
            closestDist = best ? bestDist : fallbackDist;
        }

        // Scan buildings: always for siege, fallback for regular units
        if (!closest || isSiegeUnit) {
            for (const b of this.scene.buildings.getChildren()) {
                const bOwner = b.getData('owner') as number;
                if (bOwner === myOwner) continue;
                const bhp = b.getData('hp') as number;
                if (bhp <= 0) continue;

                const bImg = b as Phaser.GameObjects.Image;
                const dx = unit.x - bImg.x;
                const dy = unit.y - bImg.y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                if (dist < closestDist) {
                    closest = b;
                    closestDist = dist;
                }
            }
        }

        if (closest) {
            const range = unit.getData('range') as number || 40;
            if (stance === UnitStance.HOLD && closestDist > range) {
                return;
            }

            unit.target = closest;
            unit.setData('explicitTarget', false);
            unit.state = UnitState.CHASING;
        }
    }

    // ─── Combat State Machine ─────────────────────────────────────────────
    private handleCombatState(unit: GameUnit, time: number): void {
        const target = unit.target as Phaser.GameObjects.Image;
        const body = unit.body as Phaser.Physics.Arcade.Body;

        if (!target || !target.scene) {
            unit.state = UnitState.IDLE;
            unit.target = null;
            if (body) body.setVelocity(0, 0);
            return;
        }

        const dx = unit.x - target.x;
        const dy = unit.y - target.y;
        const rawDist = Math.sqrt(dx * dx + dy * dy);
        const baseRange = unit.getData('range') as number || 40;

        // Adjust for building size: if target is a building, compute effective distance
        // to its nearest edge instead of center. This prevents endless chasing because
        // the unit cannot reach the center (it's inside solid collision).
        let effectiveDist = rawDist;
        let chaseTargetX = target.x;
        let chaseTargetY = target.y;
        const def = target.getData('def') as { width: number; height: number } | undefined;
        if (def) {
            const halfW = def.width / 2;
            const halfH = def.height / 2;
            // Clamp unit position to building edge rectangle to get closest approach
            const closestX = Math.max(target.x - halfW, Math.min(unit.x, target.x + halfW));
            const closestY = Math.max(target.y - halfH, Math.min(unit.y, target.y + halfH));
            effectiveDist = Math.hypot(unit.x - closestX, unit.y - closestY);
            // Chase toward the edge point, not center
            chaseTargetX = closestX;
            chaseTargetY = closestY;
        }

        const range = baseRange;
        const attackSpeed = unit.getData('attackSpeed') as number || 1000;
        const stance = unit.getData('stance') as UnitStance || UnitStance.DEFENSIVE;
        const anchor = unit.getData('anchor') || { x: unit.x, y: unit.y };
        const explicitTarget = unit.getData('explicitTarget') === true;

        // Stance constraint checks
        if (!explicitTarget) {
            if (stance === UnitStance.DEFENSIVE) {
                const tetherDist = Phaser.Math.Distance.Between(unit.x, unit.y, anchor.x, anchor.y);
                if (tetherDist > STANCE_TETHER_RADIUS) {
                    unit.target = null;
                    unit.state = UnitState.IDLE;
                    // Spread return-to-anchor paths across frames via async queue
                    this.scene.pathfinder.requestPath(
                        new Phaser.Math.Vector2(unit.x, unit.y),
                        new Phaser.Math.Vector2(anchor.x, anchor.y),
                        (path) => {
                            if (!unit.scene) return;
                            if (path && path.length > 1) {
                                unit.path = path;
                                unit.pathStep = 0;
                                unit.pathCreatedAt = time;
                            }
                        }
                    );
                    return;
                }
            } else if (stance === UnitStance.HOLD) {
                if (effectiveDist > range) {
                    body.setVelocity(0, 0);
                    unit.target = null;
                    unit.state = UnitState.IDLE;
                    return;
                }
            }
        }

        // Attack or chase

        if (effectiveDist <= range) {
            body.setVelocity(0, 0);
            const wasChasing = unit.state === UnitState.CHASING;
            unit.state = UnitState.ATTACKING;
            unit.path = null;

            // Charge impulse on first contact: give a forward velocity boost
            if (wasChasing) {
                const chargeDirX = -dx / rawDist;
                const chargeDirY = -dy / rawDist;
                body.velocity.x += chargeDirX * CHARGE_IMPULSE;
                body.velocity.y += chargeDirY * CHARGE_IMPULSE;
                // Store charge timer on squad soldiers for visual effect
                unit.setData('chargeTimer', CHARGE_IMPULSE_DURATION_MS);
            }

            // Track attacker index on target for front-rank lock / flank wrap
            if (target && target instanceof Phaser.GameObjects.Image) {
                const attackerCount = (target.getData('attackerCount') as number) || 0;
                target.setData('attackerCount', attackerCount + 1);
                unit.setData('attackerIndex', attackerCount); // 0 = first, 1 = second, etc.
            }

            // Propagate chargeTimer to soldier states for render
            const soldiers = unit.getData('soldierStates') as SoldierState[];
            if (soldiers && soldiers.length > 0) {
                const timer = unit.getData('chargeTimer') as number;
                for (const s of soldiers) {
                    s.chargeTimer = timer || 0;
                }
            }

            const now = time;
            const last = unit.lastAttackTime || 0;
            if (now - last > attackSpeed) {
                unit.lastAttackTime = now;
                this.performAttack(unit, target as GameUnit);
            }
        } else {
            unit.state = UnitState.CHASING;

            // Stable chase path: repath only when needed; never reset pathStep to 0
            // (that walked units back to the start cell → back-and-forth thrash).
            const nowMs = this.scene.time.now;
            const lastRecalc = (unit.getData('_lastPathRecalc') as number) || 0;
            const lastTarget = unit.getData('_chaseTargetPos') as { x: number; y: number } | undefined;
            const targetMoved = lastTarget
              ? Math.hypot(target.x - lastTarget.x, target.y - lastTarget.y)
              : Number.POSITIVE_INFINITY;

            const needRepath = shouldRepathChase({
              path: unit.path,
              pathStep: unit.pathStep ?? 0,
              timeSinceRecalc: nowMs - lastRecalc,
              targetMoved: Number.isFinite(targetMoved) ? targetMoved : 9999,
              distToTarget: effectiveDist,
              range,
            });

            const endStale = !!(
              unit.path
              && unit.path.length > 1
              && !pathEndNearTarget(unit.path, chaseTargetX, chaseTargetY)
              && (nowMs - lastRecalc) >= 450
            );

            if (needRepath || endStale) {
              unit.setData('_lastPathRecalc', nowMs);
              const tx = chaseTargetX, ty = chaseTargetY;
              unit.setData('_chaseTargetPos', { x: tx, y: ty });
              this.scene.pathfinder.requestPath(
                new Phaser.Math.Vector2(unit.x, unit.y),
                new Phaser.Math.Vector2(tx, ty),
                (path) => {
                  // Validate: unit alive, still chasing same-ish target, hasn't left CHASING
                  if (!unit.scene) return;
                  const t = unit.target as Phaser.GameObjects.Image;
                  if (!t || !t.scene || unit.state !== UnitState.CHASING) return;
                  const chased = unit.getData('_chaseTargetPos') as { x: number; y: number } | undefined;
                  if (!chased || Math.hypot(t.x - chased.x, t.y - chased.y) > range + 30) return;
                  if (path && path.length > 1) {
                    unit.path = path;
                    unit.pathStep = findResumePathStep(path, unit.x, unit.y);
                    unit.pathCreatedAt = this.scene.gameTime;
                  } else if (!unit.path || unit.path.length <= 1) {
                    unit.path = null;
                  }
                }
              );
            } else if (!lastTarget) {
              unit.setData('_chaseTargetPos', { x: chaseTargetX, y: chaseTargetY });
            }

            if (unit.path && unit.path.length > 1 && (unit.pathStep ?? 0) < unit.path.length) {
              this.moveAlongPath(unit);
            } else {
              // A terminal/one-point path can end at a walkable cell center short of a blocked target.
              // Keep closing directly until the attack-range check transitions to ATTACKING.
              const finalSpeed = UNIT_SPEED[unit.unitType as UnitType] || 100;
              const formation = unit.getData('formation') as FormationType || FormationType.BOX;
              const formationMultiplier = FORMATION_BONUSES[formation]?.speed || 1.0;
              const terrainModifier = this.scene.terrainSystem.getMovementModifier(unit.x, unit.y);
              const moveMult = this.scene.researchManager?.getSnapshot(unit.getData('owner') as number).movementSpeedMult ?? 1;
              const speed = finalSpeed * formationMultiplier * terrainModifier * moveMult;
              this.scene.physics.moveTo(unit, chaseTargetX, chaseTargetY, speed);
              if (unit.pathStep >= (unit.path?.length ?? 0)) unit.path = null;
            }
        }
    }

    // ─── Path Following ────────────────────────────────────────────────────
    private moveAlongPath(unit: GameUnit): void {
        if (!unit.path || unit.path.length === 0) return;

        if (unit.pathStep >= unit.path.length) {
            const body = unit.body as Phaser.Physics.Arcade.Body;
            body.setVelocity(0, 0);
            unit.path = null;
            return;
        }

        const nextPoint = unit.path[unit.pathStep];
        const dx = unit.x - nextPoint.x;
        const dy = unit.y - nextPoint.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < 4) {
            unit.pathStep++;
            // Skip duplicate nearby points
            while (unit.pathStep < unit.path.length) {
                const p = unit.path[unit.pathStep];
                const d = Phaser.Math.Distance.Between(unit.x, unit.y, p.x, p.y);
                if (d > 4) break;
                unit.pathStep++;
            }
        } else {
            const baseSpeed = UNIT_SPEED[unit.unitType as UnitType] || 100;
            const formation = unit.getData('formation') as FormationType || FormationType.BOX;
            const formationMultiplier = FORMATION_BONUSES[formation]?.speed || 1.0;

            // Apply terrain-based movement speed modifier
            const terrainModifier = this.scene.terrainSystem.getMovementModifier(unit.x, unit.y);
            const moveMult = this.scene.researchManager?.getSnapshot(unit.getData('owner') as number).movementSpeedMult ?? 1;
            const finalSpeed = baseSpeed * formationMultiplier * terrainModifier * moveMult;

            this.scene.physics.moveTo(unit, nextPoint.x, nextPoint.y, finalSpeed);
        }

        // Stale path: mid-chase clear+repath next tick (stay CHASING).
        // Non-combat still drops to IDLE so idle scan can take over.
        if (unit.pathCreatedAt && unit.path) {
            const age = this.scene.gameTime - unit.pathCreatedAt;
            const inCombat =
              unit.state === UnitState.CHASING || unit.state === UnitState.ATTACKING;
            const action = stalePathAction(age, STALE_PATH_LIFETIME, inCombat);
            if (action === 'clear_repath') {
                unit.path = null;
                // force repath on next combat tick
                unit.setData('_lastPathRecalc', 0);
            } else if (action === 'clear_idle') {
                unit.path = null;
                unit.state = UnitState.IDLE;
            }
        }
    }

    // ─── Combat Resolution ─────────────────────────────────────────────────
    private performAttack(unit: GameUnit, target: GameUnit): void {
        const isStress = !!this.scene.stressTestConfig;

        // Build the attacker's per-type damage profile (fall back to legacy flat attack)
        let profile: DamageProfile = (unit.getData('damage') as DamageProfile) || {};
        if (!profile || Object.keys(profile).length === 0) {
            profile = { [DamageType.HACK]: (unit.getData('attack') as number) || 10 };
        }

        const formation = unit.getData('formation') as FormationType || FormationType.BOX;
        const attackMult = FORMATION_BONUSES[formation]?.attack || 1.0;

