import Phaser from 'phaser';
import { MainScene } from '../MainScene';
import { Season } from '../../types';

export class AtmosphericSystem {
    private scene: MainScene;
    public clouds: Phaser.GameObjects.Sprite[] = [];

    private bloomEffect: Phaser.FX.Bloom | null = null;
    private tiltShiftEffect: unknown = null; // reserved for future DOF effect

    private vignetteEffect: Phaser.FX.Vignette | null = null;
    private cloudTextureKey = 'cloud-puff';
    private cloudCount = 20;

    // Store user's desired bloom multiplier so adaptive logic doesn't overwrite it
    private userBloomMultiplier: number = 1.0;
    // PostFX enabled/disabled toggle (user performance setting)
    private postFXEnabled: boolean = true;
    // Seasonal cloud speed multiplier (1.0 = default)
    private cloudSpeedMult: number = 1.0;
    // Seasonal terrain tint overlay
    private seasonalTint!: Phaser.GameObjects.Graphics;
    private seasonalTintTarget = { color: 0x000000, alpha: 0 };
    private seasonalTintCurrent = { color: 0x000000, alpha: 0 };
    // Track whether seasonal tint needs redraw to avoid full-screen Graphics clear/fill every frame
    private seasonalTintDirty: boolean = true;

    constructor(scene: MainScene) {
        this.scene = scene;
        this.createCloudTexture();
        this.createClouds();
        this.setupBloom();
        this.createSeasonalTint();
    }
    // Camera rect tracking for seasonal tint redraw
    private prevViewRect: Phaser.Geom.Rectangle | null = null;

    private createSeasonalTint() {
        this.seasonalTint = this.scene.add.graphics();
        this.seasonalTint.setScrollFactor(0);
        this.seasonalTint.setDepth(1000);
        this.scene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
            this.seasonalTint?.destroy();
        });
    }
    private createCloudTexture() {
        const size = 128;
        const canvas = this.scene.textures.createCanvas(this.cloudTextureKey, size, size);
        if (!canvas) return;

        const ctx = canvas.context;

        // Draw a soft radial gradient
        const grd = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
        grd.addColorStop(0, 'rgba(0, 0, 0, 1)'); // Dark center (shadow)
        grd.addColorStop(0.4, 'rgba(0, 0, 0, 0.5)');
        grd.addColorStop(1, 'rgba(0, 0, 0, 0)'); // Transparent edge

        ctx.fillStyle = grd;
        ctx.fillRect(0, 0, size, size);

        canvas.refresh();
    }

    private createClouds() {
        // Clear old if any
        this.clouds.forEach(c => c.destroy());
        this.clouds = [];

        const bounds = this.getSpawnBounds();

        for (let i = 0; i < this.cloudCount; i++) {
            const x = Phaser.Math.Between(bounds.left, bounds.right);
            const y = Phaser.Math.Between(bounds.top, bounds.bottom);

            const cloud = this.scene.add.sprite(x, y, this.cloudTextureKey);
            if (this.scene.worldLayer) this.scene.worldLayer.add(cloud);
            cloud.setDepth(15000 + i); // Stagger depth slightly so they layer
            cloud.setAlpha(Phaser.Math.FloatBetween(0.03, 0.07)); // light puffs only
            cloud.setScale(Phaser.Math.FloatBetween(4.0, 8.0)); // Big puffy clouds

            // Random rotation for variety
            cloud.setRotation(Phaser.Math.FloatBetween(0, Math.PI * 2));

            this.clouds.push(cloud);
        }
    }

    private getSpawnBounds() {
        // We want clouds to cover a large area around the camera
        // Since the map can be large, we'll just spawn them around the map "working area"
        // or relative to the initial camera view.
        // For now, let's cover a reasonable 4096x4096 area (MapSize.LARGE)
        return {
            left: -1000,
            right: 5000,
            top: -1000,
            bottom: 5000
        };
    }

    private setupBloom() {
      // Low bloom + no tiltShift — both grey midtones / kill contrast.
      // Color punch lives in ground/terrain/water, not PostFX.
      const target = this.scene.worldLayer ? this.scene.worldLayer.postFX : this.scene.cameras.main.postFX;

      this.bloomEffect = target.addBloom(0xffffff, 1, 1, 0.4, 0.5);
      this.tiltShiftEffect = null; // drop DOF blur — greys edges
      this.vignetteEffect = target.addVignette(0.5, 0.5, 0.98, 0.03);
    }

    public setBloomIntensity(intensity: number) {
        // Store user preference as a multiplier (range ~0.0 to 3.0)
        this.userBloomMultiplier = intensity;
    }

    /** Toggle PostFX (bloom/vignette) — full-screen GPU passes that dominate frame cost on iGPU. */
    public setPostFXEnabled(enabled: boolean): void {
        this.postFXEnabled = enabled;
        if (!enabled) {
            this.bloomEffect?.destroy();
            this.vignetteEffect?.destroy();
            this.bloomEffect = null;
            this.vignetteEffect = null;
            // Hide clouds when PostFX disabled to save CPU update
            this.clouds.forEach(c => c.setVisible(false));
        } else if (!this.bloomEffect || !this.vignetteEffect) {
            this.setupBloom();
            // Show clouds when PostFX re-enabled
            this.clouds.forEach(c => c.setVisible(true));
            // Mark tint dirty to ensure it redraws
            this.seasonalTintDirty = true;
        }
    }

    public update(time: number, delta: number) {
        const cam = this.scene.cameras.main;
        const viewRect = cam.worldView;

        // Track camera position for seasonal tint redraw
        const cameraMoved = !this.prevViewRect ||
            this.prevViewRect.x !== viewRect.x ||
            this.prevViewRect.y !== viewRect.y ||
            this.prevViewRect.width !== viewRect.width ||
            this.prevViewRect.height !== viewRect.height;
        if (cameraMoved) {
            this.seasonalTintDirty = true;
        }
        this.prevViewRect = Phaser.Geom.Rectangle.Clone(viewRect);

        // Bloom strength lerp only — clouds and tint run regardless of PostFX
        if (this.postFXEnabled && this.bloomEffect) {
            const zoomProgress = Phaser.Math.Clamp((cam.zoom - 0.5) / 1.5, 0, 1);
            // Mild glow only — high bloom was washing the map to grey
            const baseStrength = Phaser.Math.Linear(0.55, 0.2, zoomProgress);
            const pulse = Math.sin(time * 0.002) * 0.02;
            const dynamicTarget = Phaser.Math.Clamp(baseStrength + pulse, 0.05, 0.8);
            const target = Phaser.Math.Clamp(dynamicTarget * this.userBloomMultiplier, 0.0, 2.0);
            this.bloomEffect.strength = Phaser.Math.Linear(this.bloomEffect.strength, target, 0.08);
        }

        // Smoothly interpolate seasonal tint, only redraw when changed
        if (this.seasonalTint) {
            const t = 0.03; // ~30 frames to settle
            const prevAlpha = this.seasonalTintCurrent.alpha;
            this.seasonalTintCurrent.alpha = Phaser.Math.Linear(this.seasonalTintCurrent.alpha, this.seasonalTintTarget.alpha, t);
            this.seasonalTintCurrent.color = this.seasonalTintTarget.color;

            // Only clear/fill when alpha is changing (settling), camera moved, or marked dirty.
            // At 5000 units, skipping the per-frame clear/fill saves ~0.5ms on iGPU.
            const alphaChanged = Math.abs(this.seasonalTintCurrent.alpha - prevAlpha) > 0.001;
            if (this.seasonalTintDirty || alphaChanged) {
                this.seasonalTint.clear();
                if (this.seasonalTintCurrent.alpha > 0.005) {
                    this.seasonalTint.fillStyle(this.seasonalTintCurrent.color, this.seasonalTintCurrent.alpha);
                    this.seasonalTint.fillRect(viewRect.x - 100, viewRect.y - 100, viewRect.width + 200, viewRect.height + 200);
                }
                // Mark clean once settled and camera stable
                if (!alphaChanged && !cameraMoved) {
                    this.seasonalTintDirty = false;
                }
            }
        }

        // --- Cloud Logic (skipped when postFX disabled — no overhead) ---
        if (this.postFXEnabled) {
            // Expand wrap bounds well beyond the camera view to avoid popping
            const pad = 500;
            const wrapBounds = {
                left: viewRect.x - pad,
                right: viewRect.x + viewRect.width + pad,
                top: viewRect.y - pad,
                bottom: viewRect.y + viewRect.height + pad
            };
            const speed = 2 * this.cloudSpeedMult * (delta / 16.6);

            this.clouds.forEach(cloud => {
                // Move cloud
                cloud.x += speed * (cloud.scaleX * 0.5);
                // Wrap Logic: If cloud goes too far right, wrap to left
                if (cloud.x > wrapBounds.right) {
                    cloud.x = wrapBounds.left;
                    cloud.y = Phaser.Math.Between(wrapBounds.top, wrapBounds.bottom);
                }
                // Keep clouds contained in Y view too
                if (cloud.y > wrapBounds.bottom) {
                    cloud.y = wrapBounds.top;
                } else if (cloud.y < wrapBounds.top) {
                    cloud.y = wrapBounds.bottom;
                }
            });
        }
    }

    public applySeasonalTint(season: Season): void {
        switch (season) {
            case Season.SPRING:
                this.seasonalTintTarget = { color: 0x88CC88, alpha: 0.04 };
                this.cloudSpeedMult = 0.9;
                break;
            case Season.SUMMER:
                this.seasonalTintTarget = { color: 0xFFDD88, alpha: 0.03 };
                this.cloudSpeedMult = 0.7;
                break;
            case Season.AUTUMN:
                this.seasonalTintTarget = { color: 0xCC8833, alpha: 0.08 };
                this.cloudSpeedMult = 1.3;
                break;
            case Season.WINTER:
                this.seasonalTintTarget = { color: 0x8899CC, alpha: 0.10 };
                this.cloudSpeedMult = 1.6;
                break;
        }
        // Mark tint dirty so it redraws with new target on next update
        this.seasonalTintDirty = true;
    }

    public getWindSway(x: number, y: number, time: number): number {
        // Use Perlin-like noise (sine combination) for wind
        // Low frequency base sway
        const base = Math.sin(time * 0.0005 + x * 0.002 + y * 0.002);

        // High frequency gusts (more variation)
        const gust = Math.sin(time * 0.002 + x * 0.01 + y * 0.01) * 0.3;

        // Combine and scale
        // Return a rotation value in radians (small amplitude)
        return (base + gust) * 0.05; // +/- 0.05 - 0.08 radians (approx 3-5 degrees)
    }
}

import React, { useState, useEffect } from 'react';
import { MainMenu } from './components/MainMenu';
import { PhaserGame } from './components/PhaserGame';
import { GameUI } from './components/GameUI';
import { LoadingScreen } from './components/LoadingScreen';
import { StressTestOverlay } from './components/StressTestOverlay';
import { FactionType, GameStats, BuildingType, MapMode, MapSize, MapPreset, UnitType, FormationType, UnitStance, Age, Season, GameResult, VictoryType } from './types';
import { EVENTS, INITIAL_RESOURCES } from './constants';
import Phaser from 'phaser';

interface StressTestConfig {
  unitCount: number;
  enableEnemies?: boolean;
}

const App: React.FC = () => {
  const [gameState, setGameState] = useState<'menu' | 'playing' | 'stress-test'>('menu');
  const [isGameLoading, setIsGameLoading] = useState<boolean>(true);
  const [loadProgress, setLoadProgress] = useState<number>(0);

  const [faction, setFaction] = useState<FactionType>(FactionType.ROMANS);
  const [mapMode, setMapMode] = useState<MapMode>(MapMode.FIXED);
  const [mapSize, setMapSize] = useState<MapSize>(MapSize.MEDIUM);
  const [fowEnabled, setFowEnabled] = useState<boolean>(true);
  const [peacefulMode, setPeacefulMode] = useState<boolean>(false);
  const [treatyLength, setTreatyLength] = useState<number>(10);
  const [aiDisabled, setAiDisabled] = useState<boolean>(false);
  const [mapSeed, setMapSeed] = useState<number>(0);
  const [mapPreset, setMapPreset] = useState<MapPreset>(MapPreset.STANDARD);

  const [gameInstance, setGameInstance] = useState<Phaser.Game | null>(null);
  const [stressTestConfig, setStressTestConfig] = useState<StressTestConfig | null>(null);

  const [stats, setStats] = useState<GameStats>({
    population: 0,
    maxPopulation: 10,
    happiness: 100,
    happinessChange: 0,
    resources: INITIAL_RESOURCES,
    rates: { wood: 0, food: 0, gold: 0, foodConsumption: 0 },
    taxRate: 0,
    mapMode: MapMode.FIXED,
    peacefulMode: false,
    treatyTimeRemaining: 0,
    bloomIntensity: 1.0,
    currentFormation: FormationType.BOX,
  currentStance: UnitStance.AGGRESSIVE,
  currentAge: Age.VILLAGE,
  ageProgress: 0,
  nextAge: null,
  currentSeason: Season.SUMMER,
  notifications: [],
  activeResearch: null,
  completedTechs: [],
  gameResult: GameResult.PLAYING,
});
const [selectedCount, setSelectedCount] = useState(0);
  const [selectedCounts, setSelectedCounts] = useState<Record<string, number>>({});
  const [selectedBuildingType, setSelectedBuildingType] = useState<BuildingType | null>(null);
  const handleStart = (selectedFaction: FactionType, mode: MapMode, size: MapSize, fow: boolean, peaceful: boolean, treaty: number, disableAI: boolean, seed: number = 0, preset: MapPreset = MapPreset.STANDARD) => {
    setFaction(selectedFaction);
    setMapMode(mode);
    setMapSize(size);
    setFowEnabled(fow);
    setPeacefulMode(peaceful);
    setTreatyLength(treaty);
    setAiDisabled(disableAI);
    setMapSeed(seed);
    setMapPreset(preset);
    setStressTestConfig(null);
    setIsGameLoading(true);
    setLoadProgress(0);
    setGameState('playing');
  };

  const handleStressTestStart = (config: StressTestConfig) => {
    setFaction(FactionType.ROMANS);
    setMapMode(MapMode.FIXED);
    setMapSize(MapSize.LARGE);
    setFowEnabled(false);
    setPeacefulMode(!config.enableEnemies);
    setTreatyLength(0);
    setAiDisabled(false);
    setStressTestConfig(config);
    setIsGameLoading(true);
    setLoadProgress(0);
    setGameState('stress-test');
  };

  const handleQuit = () => {
    if (gameInstance) {
      gameInstance.destroy(true);
      setGameInstance(null);
    }
    setGameState('menu');
    setIsGameLoading(true);
    setStats({
      population: 0,
      maxPopulation: 10,
      happiness: 100,
      happinessChange: 0,
      resources: INITIAL_RESOURCES,
      rates: { wood: 0, food: 0, gold: 0, foodConsumption: 0 },
      taxRate: 0,
      mapMode: MapMode.FIXED,
      peacefulMode: false,
      treatyTimeRemaining: 0,
      bloomIntensity: 1.0,
      currentFormation: FormationType.BOX,
    currentStance: UnitStance.AGGRESSIVE,
      currentAge: Age.VILLAGE,
      ageProgress: 0,
      nextAge: null,
      currentSeason: Season.SUMMER,
      notifications: [],
      activeResearch: null,
      completedTechs: [],
      selectedBuildingInfo: null,
      gameResult: GameResult.PLAYING,
      dominanceProgress: 0,
      playerTerritoryPercent: 0,
      victoryType: VictoryType.CONQUEST,
    });
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const stressCount = parseInt(params.get('stress') || '0', 10);
    if (stressCount > 0) {
      // Defer to next tick to avoid react-hooks/set-state-in-effect
      const id = setTimeout(() => {
        handleStressTestStart({ unitCount: stressCount, enableEnemies: params.get('enemies') === 'true' });
      }, 0);
      return () => clearTimeout(id);
    }

    const progressHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      setLoadProgress(customEvent.detail);
    };
    const completeHandler = () => {
      // Add a slight artificial delay for smooth transition
      setTimeout(() => setIsGameLoading(false), 500);
    };
    const stressTestHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      handleStressTestStart(customEvent.detail);
    };

    window.addEventListener('game-load-progress', progressHandler);
    window.addEventListener('game-load-complete', completeHandler);
    window.addEventListener('stressTestStart', stressTestHandler);

    return () => {
      window.removeEventListener('game-load-progress', progressHandler);
      window.removeEventListener('game-load-complete', completeHandler);
      window.removeEventListener('stressTestStart', stressTestHandler);
    };
  }, []);

  useEffect(() => {
    if (!gameInstance) return;

    const updateHandler = (newStats: GameStats) => {
      setStats(newStats);
    };

    const selectionHandler = (data: number | { count: number; counts: Record<string, number> }) => {
      // Handle both minimal (count only) and rich (object) payloads
      if (typeof data === 'number') {
        setSelectedCount(data);
        setSelectedCounts({});
      } else {
        setSelectedCount(data.count);
        setSelectedCounts(data.counts || {});
      }
    };

    const buildingSelectionHandler = (type: BuildingType | null) => {
      setSelectedBuildingType(type);
    };

    const ageAdvancedHandler = (age: Age) => {
      setStats(prev => ({ ...prev, currentAge: age, ageProgress: 0, nextAge: null }));
    };

    gameInstance.events.on(EVENTS.UPDATE_STATS, updateHandler);
    gameInstance.events.on(EVENTS.SELECTION_CHANGED, selectionHandler);
    gameInstance.events.on(EVENTS.BUILDING_SELECTED, buildingSelectionHandler);
    gameInstance.events.on(EVENTS.AGE_ADVANCED, ageAdvancedHandler);

    const taxHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      gameInstance.events.emit(EVENTS.SET_TAX_RATE, customEvent.detail);
    };
    const centerCameraHandler = () => {
      gameInstance.events.emit(EVENTS.CENTER_CAMERA);
    };
    const speedHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      gameInstance.events.emit(EVENTS.SET_GAME_SPEED, customEvent.detail);
    };
    const bloomHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      gameInstance.events.emit(EVENTS.SET_BLOOM_INTENSITY, customEvent.detail);
    };
    const formationHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      gameInstance.events.emit('request-set-formation', customEvent.detail);
    };
    const stanceHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      gameInstance.events.emit('request-set-stance', customEvent.detail);
    };

    const researchHandler = (e: Event) => {
      const customEvent = e as CustomEvent;
      gameInstance.events.emit(EVENTS.START_RESEARCH, customEvent.detail);
    };

    const clearSelectionHandler = () => {
      gameInstance.events.emit('clear-selection');
    };

    const saveGameHandler = () => {
      gameInstance.events.emit('save-game');
    };
    const loadGameHandler = () => {
      gameInstance.events.emit('load-game');
    };

    window.addEventListener('set-tax-rate-ui', taxHandler);
    window.addEventListener('center-camera-ui', centerCameraHandler);
    window.addEventListener('set-game-speed-ui', speedHandler);
    window.addEventListener('set-bloom-intensity-ui', bloomHandler);
    window.addEventListener('request-set-formation-ui', formationHandler);
    window.addEventListener('request-set-stance-ui', stanceHandler);
    window.addEventListener('request-start-research', researchHandler);
    window.addEventListener('clear-selection', clearSelectionHandler);
    window.addEventListener('save-game', saveGameHandler);
    window.addEventListener('load-game', loadGameHandler);

    return () => {
      if (gameInstance) {
        gameInstance.events.off(EVENTS.UPDATE_STATS, updateHandler);
        gameInstance.events.off(EVENTS.SELECTION_CHANGED, selectionHandler);
        gameInstance.events.off(EVENTS.BUILDING_SELECTED, buildingSelectionHandler);
        gameInstance.events.off(EVENTS.AGE_ADVANCED, ageAdvancedHandler);
      }
      window.removeEventListener('set-tax-rate-ui', taxHandler);
      window.removeEventListener('center-camera-ui', centerCameraHandler);
      window.removeEventListener('set-game-speed-ui', speedHandler);
      window.removeEventListener('set-bloom-intensity-ui', bloomHandler);
      window.removeEventListener('request-set-formation-ui', formationHandler);
      window.removeEventListener('request-set-stance-ui', stanceHandler);
      window.removeEventListener('clear-selection', clearSelectionHandler);
      window.removeEventListener('save-game', saveGameHandler);
      window.removeEventListener('load-game', loadGameHandler);
    };
  }, [gameInstance]);

  const handleBuild = (type: BuildingType) => {
    gameInstance?.events.emit('request-build', type);
  };
  const handleSpawnUnit = (type: UnitType) => {
    gameInstance?.events.emit('request-unit-spawn', type);
  };

  const handleFilterSelection = (type: UnitType) => {
    gameInstance?.events.emit('filter-selection', type);
  };

  const handleRegrowForest = () => {
    gameInstance?.events.emit(EVENTS.REGROW_FOREST);
  };

  const handleToggleDemolish = (isActive: boolean) => {
    gameInstance?.events.emit(EVENTS.TOGGLE_DEMOLISH, isActive);
  };

  const handleAdvanceAge = () => {
    gameInstance?.events.emit(EVENTS.ADVANCE_AGE);
  };

  const handleReleaseGarrison = () => {
    gameInstance?.events.emit('release-garrison');
  };

  return (
    <div className="w-full h-screen overflow-hidden bg-black text-white relative select-none">
      {gameState === 'menu' && <MainMenu onStart={handleStart} />}

      {(gameState === 'playing' || gameState === 'stress-test') && (
        <>
          {isGameLoading && <LoadingScreen progress={loadProgress} />}
          <PhaserGame
            faction={faction}
            mapMode={mapMode}
            mapSize={mapSize}
            fowEnabled={fowEnabled}
            peacefulMode={peacefulMode}
            treatyLength={treatyLength}
            aiDisabled={aiDisabled}
            stressTestConfig={stressTestConfig}
            mapSeed={mapSeed}
            mapPreset={mapPreset}
            onGameReady={setGameInstance}
          />
          {!isGameLoading && gameState === 'playing' && (
            <GameUI
              stats={stats}
              onBuild={handleBuild}
              onSpawnUnit={handleSpawnUnit}
              onToggleDemolish={handleToggleDemolish}
              onRegrowForest={handleRegrowForest}
              onQuit={handleQuit}
              selectedCount={selectedCount}
              selectedCounts={selectedCounts}
              selectedBuildingType={selectedBuildingType}
              onFilterSelection={handleFilterSelection}
              onDemolishSelected={() => gameInstance?.events.emit(EVENTS.DEMOLISH_SELECTED)}
              onAdvanceAge={handleAdvanceAge}
              onReleaseGarrison={handleReleaseGarrison}
              currentAge={stats.currentAge}
              ageProgress={stats.ageProgress}
              nextAge={stats.nextAge}
            />
          )}
          {!isGameLoading && gameState === 'stress-test' && (
            <StressTestOverlay
              unitCount={stressTestConfig?.unitCount || 0}
              onQuit={handleQuit}
              gameInstance={gameInstance}
            />
          )}
        </>
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import Phaser from 'phaser';
import { MainScene } from '../game/MainScene';
import { FactionType, MapMode, MapSize, MapPreset } from '../types';

interface PhaserGameProps {
  faction: FactionType;
  mapMode: MapMode;
  mapSize: MapSize;
  fowEnabled: boolean;
  peacefulMode: boolean;
  treatyLength: number; // minutes
  aiDisabled: boolean;
  stressTestConfig: { unitCount: number; enableEnemies?: boolean } | null;
  mapSeed: number;
  mapPreset: MapPreset;
  onGameReady: (game: Phaser.Game) => void;
}
export const PhaserGame: React.FC<PhaserGameProps> = ({ faction, mapMode, mapSize, fowEnabled, peacefulMode, treatyLength, aiDisabled, stressTestConfig, mapSeed, mapPreset, onGameReady }) => {
  const gameRef = useRef<Phaser.Game | null>(null);

  useEffect(() => {
    if (gameRef.current) return;

    const config: Phaser.Types.Core.GameConfig = {
      type: Phaser.AUTO,
      parent: 'game-container',
      width: window.innerWidth,
      height: window.innerHeight,
      backgroundColor: '#000000',
      physics: {
