function reachable(node: MockNode, target: MockNode): boolean {
    const seen = new Set<MockNode>();
    const stack = [node];
    while (stack.length) {
        const n = stack.pop()!;
        if (n === target) return true;
        if (seen.has(n)) continue;
        seen.add(n);
        for (const out of n.__outEdges) stack.push(out);
    }
    return false;
}

