/* eslint-disable @typescript-eslint/no-explicit-any */
import { describe, it, expect, beforeEach, vi } from 'vitest';

vi.mock('phaser', () => ({
    default: { Math: { Clamp: (v: number, min: number, max: number) => Math.min(max, Math.max(min, v)) } },
}));

import { Pathfinder } from './Pathfinder';

describe('Pathfinder — JPS jump function (P0)', () => {
    let pathfinder: Pathfinder;

    beforeEach(() => {
        // Use small map for fast tests
        pathfinder = new Pathfinder(256, 256);
    });

    describe('jump function (iterative, 512-step limit)', () => {
        it('returns target immediately when start equals target', () => {
            const result = (pathfinder as any).jump(5, 5, 4, 5, 5, 5);
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('returns null when start is blocked', () => {
            // Block cell (5,5)
            pathfinder.markGrid(5 * 32 + 16, 5 * 32 + 16, 32, 32, true);
            const result = (pathfinder as any).jump(5, 5, 4, 5, 10, 10);
            expect(result).toBeNull();
        });

        it('returns null when max steps (512) exceeded on long clear diagonal', () => {
            // Create a long clear diagonal path > 512 steps
            // Start at (0,0), target at (600,600) - but map is only 256x256
            // So we test that it doesn't infinite loop and returns null when hitting map edge
            const result = (pathfinder as any).jump(0, 0, -1, 0, 255, 255);
            // Should either find target or hit map boundary
            expect(result === null || (result?.gx === 255 && result?.gy === 255)).toBe(true);
        });

        it('finds jump point at forced neighbor (horizontal)', () => {
            // Setup: horizontal corridor with forced neighbor
            // Current at (5,5), coming from (4,5) moving right (dx=1, dy=0)
            // Block (5,4) and (5,6) but leave (6,4) and (6,6) open -> forced neighbors at (6,5)
            pathfinder.markGrid(5 * 32 + 16, 4 * 32 + 16, 32, 32, true); // (5,4) blocked
            pathfinder.markGrid(5 * 32 + 16, 6 * 32 + 16, 32, 32, true); // (5,6) blocked
            // (6,4) and (6,6) are open by default

            const result = (pathfinder as any).jump(5, 5, 4, 5, 10, 5);
            // Should return (5,5) as jump point due to forced neighbors
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('finds jump point at forced neighbor (vertical)', () => {
            // Setup: vertical corridor with forced neighbor
            // Current at (5,5), coming from (5,4) moving down (dx=0, dy=1)
            // Block (4,5) and (6,5) but leave (4,6) and (6,6) open
            pathfinder.markGrid(4 * 32 + 16, 5 * 32 + 16, 32, 32, true); // (4,5) blocked
            pathfinder.markGrid(6 * 32 + 16, 5 * 32 + 16, 32, 32, true); // (6,5) blocked

            const result = (pathfinder as any).jump(5, 5, 5, 4, 5, 10);
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('finds jump point at forced neighbor (diagonal)', () => {
            // Diagonal movement from (4,4) to (5,5) (dx=1, dy=1)
            // Forced neighbor: block (4,5) but open (4,6)
            pathfinder.markGrid(4 * 32 + 16, 5 * 32 + 16, 32, 32, true); // (4,5) blocked
            // (4,6) is open by default

            const result = (pathfinder as any).jump(5, 5, 4, 4, 10, 10);
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('continues diagonal when no forced neighbors and cardinal checks negative', () => {
            // Clear diagonal path - should continue to target or boundary
            const result = (pathfinder as any).jump(2, 2, 1, 1, 10, 10);
            // Should find target (10,10) or continue until boundary
            expect(result).not.toBeNull();
            if (result) {
                expect(result.gx).toBeGreaterThanOrEqual(2);
                expect(result.gy).toBeGreaterThanOrEqual(2);
            }
        });

        it('stops at map boundary', () => {
            // Move toward map edge
            const result = (pathfinder as any).jump(250, 250, 249, 249, 255, 255);
            expect(result).not.toBeNull();
            if (result) {
                expect(result.gx).toBeLessThanOrEqual(255);
                expect(result.gy).toBeLessThanOrEqual(255);
            }
        });

        it('returns null when path blocked ahead', () => {
            // Block the path ahead
            pathfinder.markGrid(6 * 32 + 16, 6 * 32 + 16, 32, 32, true);
            pathfinder.markGrid(7 * 32 + 16, 7 * 32 + 16, 32, 32, true);

            const result = (pathfinder as any).jump(5, 5, 4, 4, 10, 10);
            // Should return null because (6,6) is blocked
            expect(result).toBeNull();
        });
    });

    describe('findPath integration', () => {
        it('returns empty path when start equals end', () => {
            const start = { x: 100, y: 100 };
            const end = { x: 100, y: 100 };
            const path = pathfinder.findPath(start as any, end as any);
            expect(path).toHaveLength(1);
            expect(path[0].x).toBe(100);
            expect(path[0].y).toBe(100);
        });

        it('finds path around simple obstacle', () => {
            // Block a horizontal line at y=160 from x=0 to x=256
            for (let gx = 0; gx < 8; gx++) {
                pathfinder.markGrid(gx * 32 + 16, 5 * 32 + 16, 32, 32, true);
            }
            // Path from (2,4) to (6,6) must go around
            const start = { x: 2 * 32 + 16, y: 4 * 32 + 16 };
            const end = { x: 6 * 32 + 16, y: 6 * 32 + 16 };
            const path = pathfinder.findPath(start as any, end as any);
            expect(path.length).toBeGreaterThan(1);
            // Path should not go through blocked cells
            for (const p of path) {
                const gx = Math.floor(p.x / 32);
                const gy = Math.floor(p.y / 32);
                if (gy === 5 && gx >= 0 && gx < 8) {
                    // This would be a blocked cell - fail
                    expect(true, `Path goes through blocked cell (${gx},${gy})`).toBe(false);
                }
            }
        });

        it('returns path to nearest unblocked when target is blocked', () => {
            // Block target cell
            pathfinder.markGrid(10 * 32 + 16, 10 * 32 + 16, 32, 32, true);
            const start = { x: 5 * 32 + 16, y: 5 * 32 + 16 };
            const end = { x: 10 * 32 + 16, y: 10 * 32 + 16 };
            const path = pathfinder.findPath(start as any, end as any);
            expect(path.length).toBeGreaterThan(0);
            // Last point should not be the blocked target
            const last = path[path.length - 1];
            expect(last.x).not.toBe(10 * 32 + 16);
            expect(last.y).not.toBe(10 * 32 + 16);
        });

        it('returns start when start is blocked and no unblocked nearby', () => {
            // Block start and surrounding area
            for (let dx = -1; dx <= 1; dx++) {
                for (let dy = -1; dy <= 1; dy++) {
                    pathfinder.markGrid((5 + dx) * 32 + 16, (5 + dy) * 32 + 16, 32, 32, true);
                }
            }
            const start = { x: 5 * 32 + 16, y: 5 * 32 + 16 };
            const end = { x: 10 * 32 + 16, y: 10 * 32 + 16 };
            const path = pathfinder.findPath(start as any, end as any);
            expect(path).toHaveLength(1);
            expect(path[0].x).toBe(start.x);
            expect(path[0].y).toBe(start.y);
        });
    });

    describe('flow field', () => {
        it('generates flow field and returns direction', () => {
            const ff = pathfinder.generateFlowField(100, 100);
            expect(ff.dirX).toBeDefined();
            expect(ff.dirY).toBeDefined();
            expect(ff.cols).toBeGreaterThan(0);
            expect(ff.rows).toBeGreaterThan(0);

            const dir = pathfinder.getFlowDirection(ff, 50, 50);
            expect(dir).not.toBeNull();
            if (dir) {
                const len = Math.sqrt(dir.x * dir.x + dir.y * dir.y);
                expect(len).toBeCloseTo(1, 2);
            }
        });

        it('returns null for stale flow field (version mismatch)', () => {
            const ff = pathfinder.generateFlowField(100, 100);
            // Simulate grid change by incrementing version
            (pathfinder as any).gridVersion++;
            const dir = pathfinder.getFlowDirection(ff, 50, 50);
            expect(dir).toBeNull();
        });

        it('caches flow field for same target', () => {
            const ff1 = pathfinder.generateFlowField(100, 100);
            const ff2 = pathfinder.generateFlowField(100, 100);
            expect(ff1).toBe(ff2);
        });
    });

    describe('path request queue', () => {
        it('queues and processes path requests', () => {
            const callback = vi.fn();
            const id = pathfinder.requestPath({ x: 100, y: 100 } as any, { x: 200, y: 200 } as any, callback);
            expect(typeof id).toBe('number');
            expect(pathfinder.getCacheStats().queueSize).toBe(1);

            pathfinder.processQueue();
            expect(callback).toHaveBeenCalled();
            expect(pathfinder.getCacheStats().queueSize).toBe(0);
        });

        it('cancels queued request', () => {
            const callback = vi.fn();
            const id = pathfinder.requestPath({ x: 100, y: 100 } as any, { x: 200, y: 200 } as any, callback);
            pathfinder.cancelRequest(id);
            expect(pathfinder.getCacheStats().queueSize).toBe(0);
            pathfinder.processQueue();
            expect(callback).not.toHaveBeenCalled();
        });
    });

    describe('stats and perf', () => {
        it('tracks paths computed', () => {
            expect(pathfinder.getCacheStats().pathsComputed).toBe(0);
            pathfinder.findPath({ x: 0, y: 0 } as any, { x: 100, y: 100 } as any);
            expect(pathfinder.getCacheStats().pathsComputed).toBe(1);
        });

        it('tracks flow fields generated', () => {
            expect(pathfinder.getCacheStats().flowFieldsGenerated).toBe(0);
            pathfinder.generateFlowField(100, 100);
            expect(pathfinder.getCacheStats().flowFieldsGenerated).toBe(1);
        });

        it('returns perf report with averages', () => {
            pathfinder.beginFrame();
            pathfinder.findPath({ x: 0, y: 0 } as any, { x: 100, y: 100 } as any);
            const report = pathfinder.getPerfReport();
            expect(report.frames).toBeGreaterThan(0);
            expect(report.avgPathMs).toBeGreaterThanOrEqual(0);
        });
    });
});

