    /**
     * Jump function: traverse until hitting a "jump point".
     * Iterative version with 512-step limit to prevent stack overflow.
     */
    private jump(gx: number, gy: number, px: number, py: number, ex: number, ey: number): { gx: number; gy: number } | null {
        const MAX_STEPS = 512;
        let steps = 0;

        let cx = gx;
        let cy = gy;
        let cpx = px;
        let cpy = py;

        while (steps < MAX_STEPS) {
            steps++;

            if (!this.isWalkable(cx, cy)) return null;
            if (cx === ex && cy === ey) return { gx: cx, gy: cy };

            const dx = cx - cpx;
            const dy = cy - cpy;
            const dxx = Math.abs(dx);
            const dyy = Math.abs(dy);

            if (dxx === 1 && dyy === 1) {
                // Diagonal
                // Forced neighbors at current position
                if ((!this.isWalkable(cx - dx, cy) && this.isWalkable(cx - dx, cy + dy)) ||
                    (!this.isWalkable(cx, cy - dy) && this.isWalkable(cx + dx, cy - dy))) {
                    return { gx: cx, gy: cy };
                }

                // Check if horizontal neighbor (cx+dx, cy) would be a jump point (has forced neighbors)
                const hx = cx + dx;
                const hy = cy;
                if (this.isWalkable(hx, hy)) {
                    // Forced neighbors for horizontal movement from (hx, hy) in direction (dx, 0)
                    if ((!this.isWalkable(hx, hy - 1) && this.isWalkable(hx + dx, hy - 1)) ||
                        (!this.isWalkable(hx, hy + 1) && this.isWalkable(hx + dx, hy + 1))) {
                        return { gx: cx, gy: cy };
                    }
                }

                // Check if vertical neighbor (cx, cy+dy) would be a jump point
                const vx = cx;
                const vy = cy + dy;
                if (this.isWalkable(vx, vy)) {
                    // Forced neighbors for vertical movement from (vx, vy) in direction (0, dy)
                    if ((!this.isWalkable(vx - 1, vy) && this.isWalkable(vx - 1, vy + dy)) ||
                        (!this.isWalkable(vx + 1, vy) && this.isWalkable(vx + 1, vy + dy))) {
                        return { gx: cx, gy: cy };
                    }
                }

                // Continue diagonal
                if (this.isWalkable(cx + dx, cy + dy)) {
                    cpx = cx;
                    cpy = cy;
                    cx = cx + dx;
                    cy = cy + dy;
                    continue;
                }
            } else if (dxx === 1) {
                // Horizontal
                if ((!this.isWalkable(cx, cy - 1) && this.isWalkable(cx + dx, cy - 1)) ||
                    (!this.isWalkable(cx, cy + 1) && this.isWalkable(cx + dx, cy + 1))) {
                    return { gx: cx, gy: cy };
                }
                if (this.isWalkable(cx + dx, cy)) {
                    cpx = cx;
                    cpy = cy;
                    cx = cx + dx;
                    continue;
                }
            } else {
                // Vertical
                if ((!this.isWalkable(cx - 1, cy) && this.isWalkable(cx - 1, cy + dy)) ||
                    (!this.isWalkable(cx + 1, cy) && this.isWalkable(cx + 1, cy + dy))) {
                    return { gx: cx, gy: cy };
                }
                if (this.isWalkable(cx, cy + dy)) {
                    cpx = cx;
                    cpy = cy;
                    cy = cy + dy;
                    continue;
                }
            }

            return null;
        }

        // Max steps reached
        return null;
    }

    private isCellBlocked(i: number): boolean {
        return this.blocked[i] === 1 || this.waterBlocked[i] === 1;
