    let pathfinder: Pathfinder;

    beforeEach(() => {
        // Use small map for fast tests (8x8 grid with CELL=32)
        pathfinder = new Pathfinder(256, 256);
    });

    describe('jump function (iterative, 512-step limit)', () => {
        it('returns target immediately when start equals target', () => {
            const result = (pathfinder as any).jump(5, 5, 4, 5, 5, 5);
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('returns null when start is blocked', () => {
            // Block cell (5,5) only (use small width so only one cell is marked)
            pathfinder.markGrid(5 * 32 + 16, 5 * 32 + 16, 2, 2, true);
            const result = (pathfinder as any).jump(5, 5, 4, 5, 7, 7);
            expect(result).toBeNull();
        });

        it('returns null when max steps (512) exceeded on long clear diagonal', () => {
            // Grid is 8x8, so max diagonal is 7 steps - well under 512
            // This test just verifies no infinite loop
            const result = (pathfinder as any).jump(0, 0, -1, 0, 7, 7);
            // Should either find target or hit map boundary
            expect(result === null || (result?.gx === 7 && result?.gy === 7)).toBe(true);
        });

        it('finds jump point at forced neighbor (horizontal)', () => {
            // Setup: horizontal corridor with forced neighbor
            // Current at (5,5), coming from (4,5) moving right (dx=1, dy=0)
            // Block (5,4) and (5,6) but leave (6,4) and (6,6) open -> forced neighbors at (6,5)
            pathfinder.markGrid(5 * 32 + 16, 4 * 32 + 16, 2, 2, true); // (5,4) blocked
            pathfinder.markGrid(5 * 32 + 16, 6 * 32 + 16, 2, 2, true); // (5,6) blocked
            // (6,4) and (6,6) are open by default

            const result = (pathfinder as any).jump(5, 5, 4, 5, 7, 5);
            // Should return (5,5) as jump point due to forced neighbors
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('finds jump point at forced neighbor (vertical)', () => {
            // Setup: vertical corridor with forced neighbor
            // Current at (5,5), coming from (5,4) moving down (dx=0, dy=1)
            // Block (4,5) and (6,5) but leave (4,6) and (6,6) open
            pathfinder.markGrid(4 * 32 + 16, 5 * 32 + 16, 2, 2, true); // (4,5) blocked
            pathfinder.markGrid(6 * 32 + 16, 5 * 32 + 16, 2, 2, true); // (6,5) blocked

            const result = (pathfinder as any).jump(5, 5, 5, 4, 5, 7);
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('finds jump point at forced neighbor (diagonal)', () => {
            // Diagonal movement from (4,4) to (5,5) (dx=1, dy=1)
            // Forced neighbor: block (4,5) but open (4,6)
            pathfinder.markGrid(4 * 32 + 16, 5 * 32 + 16, 2, 2, true); // (4,5) blocked
            // (4,6) is open by default

            const result = (pathfinder as any).jump(5, 5, 4, 4, 7, 7);
            expect(result).toEqual({ gx: 5, gy: 5 });
        });

        it('continues diagonal when no forced neighbors and cardinal checks negative', () => {
            // Clear diagonal path - should continue to target or boundary
            const result = (pathfinder as any).jump(2, 2, 1, 1, 7, 7);
            // Should find target (7,7) or continue until boundary
            expect(result).not.toBeNull();
            if (result) {
                expect(result.gx).toBeGreaterThanOrEqual(2);
                expect(result.gy).toBeGreaterThanOrEqual(2);
            }
        });

        it('stops at map boundary', () => {
            // Move toward map edge (grid is 8x8, valid indices 0-7)
            const result = (pathfinder as any).jump(6, 6, 5, 5, 7, 7);
            expect(result).not.toBeNull();
            if (result) {
                expect(result.gx).toBeLessThanOrEqual(7);
                expect(result.gy).toBeLessThanOrEqual(7);
            }
        });

        it('returns null when path blocked ahead', () => {
            // Block the path ahead at (6,6) and (7,7)
            // But we must NOT block cells that create forced neighbors for horizontal/vertical checks
            // Block (6,6) - this will create forced neighbor for horizontal from (6,5) if (6,7) open
            // So block a full diagonal line: (6,6), (7,7)
            pathfinder.markGrid(6 * 32 + 16, 6 * 32 + 16, 2, 2, true);
            pathfinder.markGrid(7 * 32 + 16, 7 * 32 + 16, 2, 2, true);
            // Also block (6,7) and (7,6) to avoid forced neighbors
            pathfinder.markGrid(6 * 32 + 16, 7 * 32 + 16, 2, 2, true);
            pathfinder.markGrid(7 * 32 + 16, 6 * 32 + 16, 2, 2, true);

            const result = (pathfinder as any).jump(5, 5, 4, 4, 7, 7);
            // Should return null because diagonal path is blocked
            expect(result).toBeNull();
        });

