it('returns path to nearest unblocked when target is blocked', () => {
    // Block target cell
    pathfinder.markGrid(6 * 32 + 16, 6 * 32 + 16, 2, 2, true);
    const start = { x: 2 * 32 + 16, y: 2 * 32 + 16 };
    const end = { x: 6 * 32 + 16, y: 6 * 32 + 16 };
    const path = pathfinder.findPath(start as any, end as any);
    expect(path.length).toBeGreaterThan(0);
    // Last point should not be the blocked target
    const last = path[path.length - 1];
    expect(last.x).not.toBe(6 * 32 + 16);
    expect(last.y).not.toBe(6 * 32 + 16);
});

