export enum UnitState {
  IDLE = 'idle',
  MOVING_TO_WORK = 'moving_to_work',
  WORKING = 'working',
  GATHERING = 'gathering',
  CARRYING = 'carrying',
  MOVING_TO_RALLY = 'moving_to_rally',
  WANDERING = 'wandering',
  CHASING = 'chasing',
  ATTACKING = 'attacking'
}

/** Per-soldier steering mode within a squad. */
export enum SoldierSteeringMode {
  /** Soldier follows formation slot strictly. */
  FORMATION = 'formation',
  /** Soldier engages in melee: 1v1 lock, flank wrap, charge impulse. */
  COMBAT = 'combat'
}

