private getSpawnBounds() {
    // We want clouds to cover a large area around the camera
    // Since the map can be large, we'll just spawn them around the map "working area"
    // or relative to the initial camera view.
    // For now, let's cover a reasonable 4096x4096 area (MapSize.LARGE)
    return {
        left: -1000,
        right: 5000,
        top: -1000,
        bottom: 5000
    };
}

private recycleCloud(cloud: Phaser.GameObjects.Sprite, viewBounds: { left: number; right: number; top: number; bottom: number }) {
    cloud.setData('active', false);
    cloud.setVisible(false);

    // Remove from active list
    const idx = this.activeClouds.indexOf(cloud);
    if (idx !== -1) this.activeClouds.splice(idx, 1);

    // Add to pool
    this.cloudPool.push(cloud);
}

private spawnCloudAtEdge(viewBounds: { left: number; right: number; top: number; bottom: number }): Phaser.GameObjects.Sprite | null {
    if (this.cloudPool.length === 0) return null;

    const cloud = this.cloudPool.pop()!;

    // Spawn at random edge of view bounds
    const edge = Phaser.Math.Between(0, 3);
    let x: number, y: number;

    switch (edge) {
        case 0: // Left edge
            x = viewBounds.left;
            y = Phaser.Math.Between(viewBounds.top, viewBounds.bottom);
            break;
        case 1: // Right edge
            x = viewBounds.right;
            y = Phaser.Math.Between(viewBounds.top, viewBounds.bottom);
            break;
        case 2: // Top edge
            x = Phaser.Math.Between(viewBounds.left, viewBounds.right);
            y = viewBounds.top;
            break;
        case 3: // Bottom edge
            x = Phaser.Math.Between(viewBounds.left, viewBounds.right);
            y = viewBounds.bottom;
            break;
    }

    cloud.setPosition(x, y);
    cloud.setVisible(true);
    cloud.setData('active', true);
    cloud.setAlpha(Phaser.Math.FloatBetween(0.03, 0.07));
    cloud.setScale(Phaser.Math.FloatBetween(4.0, 8.0));
    cloud.setRotation(Phaser.Math.FloatBetween(0, Math.PI * 2));

    this.activeClouds.push(cloud);
    return cloud;
}

private maintainActiveClouds(viewBounds: { left: number; right: number; top: number; bottom: number }) {
    while (this.activeClouds.length < this.maxActiveClouds && this.cloudPool.length > 0) {
        this.spawnCloudAtEdge(viewBounds);
    }
}

