// --- Cloud Logic (skipped when postFX disabled or zoom < 0.5 — no overhead) ---
const cloudActive = this.postFXEnabled && cam.zoom >= 0.5;
if (!cloudActive) {
    // Recycle all active clouds (zoom too low or PostFX off) — zero overhead
    for (let i = this.activeClouds.length - 1; i >= 0; i--) {
        this.recycleCloud(this.activeClouds[i]);
    }
} else {
    // Viewport culling bounds with 500px padding
    const pad = 500;
    const viewBounds = {
        left: viewRect.x - pad,
        right: viewRect.x + viewRect.width + pad,
        top: viewRect.y - pad,
        bottom: viewRect.y + viewRect.height + pad
    };

    // Maintain pool of active clouds (max 12)
    this.maintainActiveClouds(viewBounds);

    const speed = 2 * this.cloudSpeedMult * (delta / 16.6);

    // Only update active clouds within view bounds + padding
    for (let i = this.activeClouds.length - 1; i >= 0; i--) {
        const cloud = this.activeClouds[i];

        // Viewport culling: recycle clouds outside bounds
        if (cloud.x < viewBounds.left || cloud.x > viewBounds.right ||
            cloud.y < viewBounds.top || cloud.y > viewBounds.bottom) {
            this.recycleCloud(cloud);
            continue;
        }

        // Move cloud
        cloud.x += speed * (cloud.scaleX * 0.5);
    }
}

